function acceptCloudSnapshot(raw,{allowClearedStorage=false}={}){
 if(localStorage.getItem(STORAGE)!==storageBaseline&&!(allowClearedStorage&&localStorage.getItem(STORAGE)===null))throw Error('Místní kampaň se mezitím změnila v jiné záložce.');
 const incoming=normalizeLegacyCustomPrices(validate(JSON.parse(raw)));
 localStorage.setItem(STORAGE,raw);storageBaseline=raw;data=incoming;
 selected=null;view='characters';encounterSelection=new Set();
 // Reload after the connected credentials have been stored by the caller.
 setTimeout(()=>window.location.reload(),1200);
}
const cloudStorage={
 getItem(key){return localStorage.getItem(key)},
 setItem(key,value){
  if(key===STORAGE&&window.__hmkOutdatedBuild)throw Error('Byla vydána nová verze aplikace. Obnovte stránku, než uložíte další herní akci.');
  if(key===STORAGE&&cloudSync&&!cloudSync.canWrite())throw Error('Nejprve připojte GitHub Cloud; tento prohlížeč nesmí zapsat starší stav.');
  // Defence in depth: even a legacy direct storage writer may not publish
  // uncommitted episode Skill Test evidence behind mutate()/save().
  if(key===STORAGE&&episodeStageBaseline&&!episodeFinalCommitInFlight&&!episodeIndependentMutationInFlight)
   throw Error('Nelze uložit rozpracované výsledky Cestování mimo dokončení celé epizody.');
  const previous=key===STORAGE?localStorage.getItem(key):null;
  localStorage.setItem(key,value);
  if(key===STORAGE&&cloudSync&&previous!==value)cloudSync.onLocalWrite(value);
 },
 removeItem(key){if(key===STORAGE&&cloudSync&&!cloudSync.canWrite())throw Error('GitHub Cloud není připojen.');localStorage.removeItem(key)}
};
cloudSync=createGitHubCloudSync({localStorage,sessionStorage,storageKey:STORAGE,
 validate:incoming=>validate(incoming),
 readLocal:()=>localStorage.getItem(STORAGE)||JSON.stringify(data),
 applyRemote:acceptCloudSnapshot,
 approveReplace:()=>true,
 onStatus:()=>{const node=document.querySelector('[data-cloud-status]');if(node)node.textContent=cloudStatusLabel()+(cloudSync?.issue?' · '+cloudSync.issue:'');const side=document.querySelector('[data-cloud-sidebar]');if(side)side.textContent=cloudStatusLabel();const block=document.querySelector('[data-cloud-block-banner]');if(block)block.hidden=cloudSync?.canWrite()??true;}
});
let catalogStatus='all'; // presentation-only; never persisted
let libraryTab='melee',libraryPage=0,libraryRecipientId=null,libraryOtherFilter='all'; // presentation-only, not stored
// Older custom 'other' items stored the editor's 'Cena / hodnota' as text
// under properties.value while catalogue and purchases read pricePence.
// Upgrade ONLY unambiguous, whole, explicitly entered numeric prices; no
// generic text valuation is guessed to be spendable campaign money.
function normalizeLegacyCustomPrices(doc){
 migrateLegacyBandageQuantities(doc);
 for(const i of doc.items||[]){
  if(i?.builtin||i?.category!=='other'||!i.properties||i.properties.pricePence!==undefined)continue;
  const raw=i.properties.value;
  if(typeof raw!=='string'||!/^\s*(?:0|[1-9]\d*)\s*(?:d)?\s*$/i.test(raw))continue;
  const price=Number(raw.trim().replace(/\s*d\s*$/i,''));
  if(Number.isSafeInteger(price)&&price>=0&&price<=999999999)i.properties.pricePence=price;
 }
 return doc;
}
try{const saved=localStorage.getItem(STORAGE);if(saved)data=normalizeLegacyCustomPrices(validate(JSON.parse(saved)));storageBaseline=saved;}catch(e){storageReadOnly=true;notice='POZOR: Původní data se nepodařilo načíst. Zápisy jsou zablokovány, aby se nepřepsala. Zálohujte data prohlížeče a opravte úložiště.';console.error(e)}
// Restore the encounter draft only after character IDs are available.
// On unreadable database data, do not rehydrate potentially stale selections.
if(!storageReadOnly){
 encounterSelection=readEncounterDraft();
 const checkpoint=data.combatRuntime;
 if(checkpoint?.sequence){
  encounterSelection=new Set(checkpoint.participants);
  // A checkpoint is stronger evidence than a stale per-tab encounter draft.
  persistEncounterDraft();
 }
}
const trainingOpenMinute600=(proof,due)=>proof?.calendarDayEligibility600===true?calendarDayStart600(due):due;
function validateAnimalTrainingCalendar590(d){
 const journal=d?.journal||[],starts=new Map(),linked=new Set(),animals=new Map();
 for(const owner of d?.characters||[])for(const animal of owner.hmk?.livestock||[])animals.set(animal.id,animal);
 for(const row of journal){
  const proof=row.calendarAnimalTrainingStart590;if(!proof)continue;
  const animal=animals.get(proof.animalId);
  if(proof.format!=='animal-training-start-590'||!animal||animal.ownerId!==proof.ownerId||
     row.characterId!==proof.ownerId||row.calendarCampaignId!==animal.campaignId||
     !Number.isSafeInteger(proof.startMinute)||proof.startMinute<animal.minute||
     row.campaignMinute!==proof.startMinute||proof.requiredDays!==180||
     proof.dueMinute!==proof.startMinute+180*1440||
     (proof.calendarDayEligibility600!==undefined&&proof.calendarDayEligibility600!==true)||starts.has(row.id))
   throw Error('Animalcraft: nepřípustná změna kalendářního dokladu zahájení výcviku.');
  starts.set(row.id,{row,proof});
 }
 const fishingStarts=new Map(),fishingUsed=new Set();
 for(const row of journal){
  const x=row.calendarFishingStart590;if(!x)continue;
  if(x.format!=='fishing-start-590'||x.actorId!==row.characterId||
     !d.characters.some(c=>c.id===x.actorId&&!c.archived)||
     !Number.isSafeInteger(x.startMinute)||x.startMinute<0||
     row.campaignMinute!==x.startMinute||x.dueMinute!==x.startMinute+240||
     typeof row.calendarCampaignId!=='string'||!row.calendarCampaignId)
   throw Error('Fishing: neplatný počáteční kalendářní doklad čtyřhodinové činnosti.');
  fishingStarts.set(row.id,{row,x});
 }
 for(const row of journal){
  const link=row.calendarFishingSVStart590;if(!link)continue;
  const start=fishingStarts.get(link.startId),p=row.skillTestProof;
  if(!start||fishingUsed.has(link.startId)||row.characterId!==start.row.characterId||
     row.calendarCampaignId!==start.row.calendarCampaignId||
     !Number.isSafeInteger(row.campaignMinute)||row.campaignMinute<start.x.dueMinute||
     link.dueMinute!==start.x.dueMinute||
     p?.type!=='secondary-mastery-value-test'||(p.skills?.[0]||p.skill)!=='Fishing')
   throw Error('Fishing: výsledek SV nesouhlasí se čtyřhodinovým dokladem ani s herním časem.');
  fishingUsed.add(link.startId);
 }
 for(const row of journal){
  const link=row.calendarAnimalTraining590;if(!link)continue;
  const start=starts.get(link.startId),animal=animals.get(link.animalId),training=row.skillTestProof;
  if(!start||!animal||link.animalId!==start.proof.animalId||
     row.characterId!==animal.ownerId||row.calendarCampaignId!==animal.campaignId||
     row.livestockTraining?.animalId!==animal.id||training?.type!=='animal-training'||
     link.dueMinute!==start.proof.startMinute+(training.months||0)*30*1440||
     !Number.isSafeInteger(row.campaignMinute)||row.campaignMinute<trainingOpenMinute600(start.proof,link.dueMinute)||
     linked.has(link.startId))
   throw Error('Animalcraft: datum, identita nebo jedinečnost dokončeného výcviku nesouhlasí s kalendářem.');
  linked.add(link.startId);
 }
 return true;
}
function assertAnimalTrainingCalendarAppendOnly590(before,after){
 const next=new Map((after?.journal||[]).filter(j=>j.calendarAnimalTrainingStart590||j.calendarAnimalTraining590||j.calendarFishingStart590||j.calendarFishingSVStart590).map(j=>[j.id,j]));
 for(const old of before?.journal||[]){if(!old.calendarAnimalTrainingStart590&&!old.calendarAnimalTraining590&&!old.calendarFishingStart590&&!old.calendarFishingSVStart590)continue;
  if(!next.has(old.id)||JSON.stringify(next.get(old.id))!==JSON.stringify(old))
   throw Error('Animalcraft: kalendářní doklad nelze změnit ani odstranit.');}
}
