 const departed=existing.filter(x=>!x.active&&(!stableOnly||!!x.ownerAnimalId)&&(!ownerId||x.ownerId===ownerId)).slice(-15).reverse();
 const archived=departed.length?`<details class="hmk-bestiary-archive"><summary>Archiv ukončených účastí (${departed.length} posledních)</summary><p class="hc-hint">Zranění, Shock a závěrečný výsledek jsou neměnné historické doklady. Zde ani v kalendáři již nevznikají povinné zdravotní testy této dočasné bytosti.</p><div class="catalog-scroll"><table class="catalog-spec"><thead><tr><th>Tvor</th><th>Rozhodnutí GM</th><th>Zdraví při ukončení</th></tr></thead><tbody>${departed.map(x=>{const p=data.journal.findLast(j=>j.bestiaryDeparture93760?.targetId===x.id)?.bestiaryDeparture93760;const h=p?.medicalSnapshot;return `<tr><td>${esc(x.name)}</td><td>${esc(p?BESTIARY_DEPARTURE_OUTCOMES_93760[p.outcome]:'Dřívější ukončení bez uvedeného výsledku')}</td><td>${h?esc('Shock '+h.shock+' · '+h.wounds.filter(w=>!w.healed).length+' otevřených ran'):'Historické zranění zachováno v archivu'}</td></tr>`}).join('')}</tbody></table></div></details>`:'';
 const stable=animals.filter(x=>x.spec.bestiaryId&&(!ownerId||x.ownerId===ownerId));
