/** One optional cryptographic dX button for clearly identified, existing
 * rule-form dice fields. The original form remains the only rule executor;
 * manual numeric input is unchanged. Ambiguous numbers are NEVER rolled.
 * This UI helper does not claim a recorded software provenance unless the
 * destination rule executor persists a matching physical-dice proof.
 */
function enhanceHMKDiceFields(){
 const app=document.getElementById('app');if(!app)return;
 const legal=new Set([4,6,8,10,12,20,30,100]);
 for(const input of app.querySelectorAll('form input[type="number"]')){
  if(input.nextElementSibling?.dataset?.hmkGeneralAutoDie==='true'||input.disabled||input.readOnly||input.closest('#campaign-expedition-form')||input.closest('.hc-calendar-recovery-die')||input.closest('[data-episode-medical-rolls]'))continue;
  const label=input.closest('label');if(!label)continue;
  if(label.querySelector('[data-episode-die]'))continue; // A dedicated episode dX generator is already present.
  // Existing dedicated generators already know each rule's roll provenance.
  // Never put a second general button next to them.
  const sibling=label.nextElementSibling;
  // A dedicated generator can be a sibling of the label OR inside the label;
  // never duplicate it or replace its existing provenance behavior.
  if(label.querySelector('button[data-hmk-general-auto-die],button[data-hmk-recovery-generate],button[data-hmk-calendar-auto-die],button[data-hmk-creation-roll],button[data-hmk-creation-die],button[data-episode-medical-die]'))continue;
  if(sibling?.tagName==='BUTTON'&&([...sibling.attributes].some(a=>a.name.startsWith('data-')&&/roll|die|dice|generate/i.test(a.name))||/⚄|generovat|hodit/i.test(sibling.textContent||'')))continue;
  const raw=label.textContent||'';
  const match=raw.match(/(?:^|[^a-zA-Z0-9])d(4|6|8|10|12|20|30|100)(?![0-9])/i);
  if(!match)continue;
  const faces=Number(match[1]);if(!legal.has(faces)||(input.max!==''&&Number(input.max)!==faces))continue;
  const min=input.min===''?1:Number(input.min);if(!Number.isFinite(min)||min>1||min<0)continue;
  const b=document.createElement('button');b.type='button';b.className='hc-small';
  b.dataset.hmkGeneralAutoDie='true';b.dataset.hmkDieFaces=String(faces);
  b.classList.add('hc-provision-generate');
  b.textContent='⚄ d'+faces;b.setAttribute('aria-label','Vygenerovat hod d'+faces+' do tohoto pole');
  input.insertAdjacentElement('afterend',b);
 }
}
document.addEventListener('click',e=>{
 const b=e.target.closest?.('[data-hmk-general-auto-die]');if(!b)return;
 e.preventDefault();e.stopImmediatePropagation();
 const input=b.previousElementSibling,faces=Number(b.dataset.hmkDieFaces);
 if(!(input instanceof HTMLInputElement)||input.type!=='number'||input.disabled||input.readOnly)return;
 try{const value=secureHMKDie(faces);input.value=String(value);input.dataset.hmkAutoDice=input.value;
  input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}));
  b.textContent='⚄ d'+faces+' = '+value;
 }catch(err){alert('Automatický hod není dostupný: '+err.message);}
},true);
document.addEventListener('input',event=>{
 const field=event.target;if(!(field instanceof HTMLInputElement)||field.type!=='number')return;
 // User typing creates a trusted browser event; generated buttons dispatch an
 // untrusted update after first marking the exact recorded value.
 if(event.isTrusted&&field.dataset.hmkAutoDice)delete field.dataset.hmkAutoDice;
},true);

