document.addEventListener('click',e=>{
 const button=e.target.closest?.('[data-hmk-followup-open-598]');if(!button)return;
 e.preventDefault();e.stopImmediatePropagation();
 if(view!=='skills'||activeSkillTab!=='followups')return;
 const root=document.getElementById('hmk-skill-workbench'),choice=root?.querySelector('[data-hmk-followup-choice-598]'),source=root?.querySelector('[data-hmk-followup-source-598]'),display=root?.querySelector('[data-hmk-followup-display-598]');
 if(!choice?.value||!source||!display)return;
 const before=display.querySelector('form[data-hmk-followup-entry-598]');if(before)source.append(before);
 const form=root.querySelector(`form[data-hmk-followup-entry-598="${choice.value}"]`);
 if(!form)return;
 display.replaceChildren();
 const caption=document.createElement('h3');caption.textContent=choice.selectedOptions[0]?.textContent||'Navazující hod';
 const info=document.createElement('p');info.className='tiny muted';info.textContent='Pouhý výběr a otevření nic neukládá. Proveďte skutečný hod a potvrďte příslušné tlačítko ve formuláři.';
 display.append(caption,info,form);
 form.hidden=false;
},true);

function render(){
 if(episodeActiveSkillRequestId){
  const r=episodePendingSkillRequest;
  if(!r||r.status!=='waiting'||r.id!==episodeActiveSkillRequestId||
   view!=='skills'||activeSkillTab!==(episodeSkillNeedsSV(r.field)?'value':'secondary')||selected!==r.actorId||
   (episodeSkillNeedsSV(r.field)&&(skillSVChoice595?.kind!=='ordinary'||skillSVChoice595?.value!==r.skill)))
   episodeActiveSkillRequestId=null;
 }
 if(view!=='encounter')stagedEncounterSelection=null; // no unattended roster changes survive navigation
 // Every return from another screen starts with an operational Skill Tests
 // selector. Direct handoffs from a stable or a calendar retain their requested
 // test, but cannot inherit an unrelated stale Success Value selection.
 if(view==='skills'&&lastRenderedSkillRoute596!==null&&lastRenderedSkillRoute596!=='skills'){
  // A travel handoff is an explicit Success Value route: never replace it
  // with an unrelated Secondary Mastery form when changing chapters.
  const travelSkill=episodePendingSkillRequest?.status==='waiting'&&
   episodeActiveSkillRequestId===episodePendingSkillRequest.id&&
   episodePendingSkillRequest.campaignId===campaignKey(data.campaignClock)&&
   episodePendingSkillRequest.minute===data.campaignClock?.minute;
  if(!travelSkill)skillSVChoice595=null;
  const linked=!!(travelSkill||pendingStableAnimalcraftId||pendingTrekHandoff||pendingTrackingAwarenessId);
  // Calendar CF navigation deliberately targets the existing follow-up form;
  // do not reset it to an unrelated fresh Skill Test tab.
  if(activeSkillTab!=='followups')activeSkillTab=linked?(travelSkill&&!episodeSkillNeedsSV(episodePendingSkillRequest.field)?'secondary':'value'):'secondary';
 }
 lastRenderedSkillRoute596=view;
 // Deny all paths to partially generated sheets, even routes that set view
 // directly without clicking a registry card (import, skill link, wizard exit).
 if(view==='sheet'){
  const c=character(selected),gate=characterJournalReadiness(c);
  if(!gate.ready){
   activeSheetSection='overview';sheetEditingId=null;overlay=null;
   view=c?.hmk?.creation?'creation':'characters';
   notice=gate.reason+' Dokončete pravidlovou tvorbu a její závěrečnou revizi.';
  }
 }
 if(view==='sheet'&&isCharacterSpecialtySection(activeSheetSection)&&!characterSpecialtyById(character(selected),activeSheetSection))activeSheetSection='overview';
 // The sidebar has its own scrolling container. Rendering replaces its DOM node,
 // so retain the actual scroll position instead of resetting the menu to the top.
 const app=document.getElementById('app');
 // A field hover bubble must not remain on screen after switching chapters.
 const obsoleteTooltip=document.querySelector('.hmk-journal-floating-tooltip');
 if(obsoleteTooltip)obsoleteTooltip.hidden=true;
 const sidebarPosition=app.querySelector('.layout>.nav')?.scrollTop??0;
 const nextRoute=currentUiRoute();
 if(!uiNavigationRestoring)uiNavigation.visit(nextRoute,{scrollY:window.scrollY});
 writeGuidedDraft();
 app.innerHTML=main()+(overlay||'');
 episodeConfigureSkillGate(app);
 stableTrainingJump597=false;
 hideVisibleTechnicalUUIDs(app);
 decorateHumanJSONReferences(app);
 hydrateSkillFollowupChoices598(app);
 applySelectedSV595(app);
 enrichAnimalTrainingForms(app);
 decorateSkillContinuationHelp(app);
 updateFollowupDiceGuides(app);
 decorateTimedSkillProject591(app);
 refreshWritingWork591(app);
 decorateFishingCalendarStart590(app);
 refreshStableAnimalcraftSVGate590(app);
 decorateStableUI580(app);
 // Fit precisely fifteen actual item rows, regardless of wrapped item labels.
 for(const container of app.querySelectorAll('.inv-table-scroll.inv-15-rows')){
  const table=container.querySelector('table'),rows=[...(table?.tBodies?.[0]?.rows||[])];
  if(rows.length>15){
   const head=table.tHead?.getBoundingClientRect().height||0;
   const visible=rows.slice(0,15).reduce((n,r)=>n+r.getBoundingClientRect().height,0);
   container.style.maxHeight=Math.ceil(head+visible+2)+'px';
  }else container.style.maxHeight='none';
 }
  hskAutoPopulateSkinForms(app);
 const sidebar=app.querySelector('.layout>.nav');
 if(sidebar)sidebar.scrollTop=sidebarPosition;
 refreshAllCalendarHealingFields();
 enhanceHMKDiceFields();
 syncWeatherCarePanel();
 initializeTimeEpisodeForm(app.querySelector('#hmk-time-episode-form'));
 decorateTimeEpisodeExclusiveLock(app);
}
// Follow-up panels may appear after a skill proof is appended without a full render.
// Observe only added DOM nodes; attribute edits from help decoration do not loop.
const skillFollowupObserver=new MutationObserver(records=>{
 if(records.some(record=>[...record.addedNodes].some(node=>node.nodeType===1&&(
  node.matches?.('form,section,div,fieldset,label,input')||
  node.querySelector?.('form[data-hmk-animal-training],form[data-skill-critical-form],input[type=number]')))))
   {const root=document.getElementById('app');enrichAnimalTrainingForms(root);decorateSkillContinuationHelp(root);updateFollowupDiceGuides(root);decorateTimedSkillProject591(root);enhanceHMKDiceFields();syncWeatherCarePanel();hideVisibleTechnicalUUIDs(root);decorateHumanJSONReferences(root);}
});
skillFollowupObserver.observe(document.getElementById('app'),{subtree:true,childList:true});
// v93.783: a Secondary Roll can become usable WITHOUT a render or added DOM
// node (the existing input only changes disabled=true -> false). Revisit ONLY
// these enable transitions. The general dice helper skips disabled fields during
// initial render, so otherwise the now-required d10 has no generator.
// No dice are rolled here; this merely adds the same optional button used by
// all other numeric rule forms, preserving manual input and submit validation.
const hmkEnabledDieObserver=new MutationObserver(records=>{
 if(records.some(r=>r.type==='attributes'&&r.target instanceof HTMLInputElement&&
  r.target.type==='number'&&!r.target.disabled))enhanceHMKDiceFields();
});
hmkEnabledDieObserver.observe(document.getElementById('app'),{
 subtree:true,attributes:true,attributeFilter:['disabled']
});
// On narrow layouts the navigation joins the page scroll instead of using
// its own scroll container. Keep the viewport at the same position on sidebar
// clicks, rather than allowing focus/scroll anchoring to jump to page top.
document.addEventListener('click',e=>{
 if(!e.target.closest?.('.nav button'))return;
 const previousY=window.scrollY;
 requestAnimationFrame(()=>{
  if(Math.abs(window.scrollY-previousY)>1){
   window.scrollTo({top:previousY,behavior:'instant'});
  }
 });
},true);
function ask(msg){return uiConfirm(msg)}
// HMK p.187: independent Fear/Aberrance form, ONE existing full-record CAS.
document.addEventListener('submit',event=>{
 const form=event.target;
 if(!['hmk-fear-exposure-form','hmk-fear-safe-form','hmk-fear-reaction-form'].includes(form?.id))return;
 event.preventDefault();event.stopImmediatePropagation();
 if(storageReadOnly){alert('Úložiště je v read-only stavu. Žádný fyzický hod neopakujte.');return}
 const v=Object.fromEntries(new FormData(form));
 try{
  const args={document:data,characterId:v.characterId,eventId:uuid(),storage:cloudStorage,
   key:STORAGE,baseline:storageBaseline,gmConfirmed:v.gmConfirmed==='on'};
  let result;
  if(form.id==='hmk-fear-exposure-form')result=persistFearExposure({...args,
   sourceKind:v.sourceKind,sourceId:v.sourceKind==='character'?v.sourceCharacter:v.sourceId,
   sourceDescription:v.sourceDescription,aberrance:Number(v.aberrance),d100:Number(v.d100),
   gmConfirmedSource:v.gmConfirmedSource==='on'});
  else if(form.id==='hmk-fear-safe-form'){
   const ref=JSON.parse(v.fearRef||'null');
   if(!Array.isArray(ref)||ref.length!==2||ref[0]!==v.characterId&&v.characterId)throw Error('Neplatný zdroj zotavení');
   result=persistFearSafeRecovery({...args,characterId:ref[0],sourceEventId:ref[1],
    elapsedMinutes:Number(v.elapsedMinutes),safeFromSource:v.safeFromSource==='on',outOfLOS:v.outOfLOS==='on'});
  }
  else result=persistFearEndTurnReaction({...args,d100:Number(v.d100)});
  if(!result.ok){if(result.readOnly)storageReadOnly=true;
   alert('Fear nebyl bezpečně zapsán: '+result.code);render();return}
  data=result.document;storageBaseline=result.serialized;
  mirrorInitiative(validateEncounterSequence(data.combatRuntime.sequence),data.combatRuntime.clock);
  notice='Fear / Aberrance: fyzický výsledek a následky jsou uloženy jedním kontrolním bodem.';
  render();
 }catch(error){alert('Fear / Aberrance — bez zápisu: '+error.message)}
},true);
// G04 guided source / shared-IR: only this route can submit its physical dice.
// HMK p.57: post-creation Perception switch through the SAME CAS mutation boundary.
document.addEventListener('submit',event=>{
 const form=event.target;if(form.id!=='hmk-perception-mode-form')return;
 event.preventDefault();event.stopImmediatePropagation();
 if(combatActorLocked93725(selected))return alert('Změna Perception účastníka boje patří do Combat.');
 const original=character(selected);if(!original?.hmk?.creation)return alert('Nejprve otevřete Character Creation.');
 const v=Object.fromEntries(new FormData(form)),dice={};
 for(const k of ['eye','hrg','sml'])if(String(v[k]??'').trim())dice[k]=String(v[k]).split(',').map(x=>x.trim());
 let update;
 try{update=setPerceptionMode(original,{mode:v.mode,dice});syncCreationSkills(update.hmk,uuid);assertCreationInvariants(update)}
 catch(err){return alert('HMK Perception: '+err.message)}
 mutate(()=>{const item=character(selected);if(!item)throw Error('Postava zmizela');Object.assign(item,update)});
},true);

