function hskTrekkingWeatherForm(entry){
 // A confirmed v93.676 travel episode owns the medical handoff for its
 // original weather roll. Never offer the older watch-scoped executor too.
 if(data.journal.some(j=>j.calendarCampaignId===entry?.calendarCampaignId&&
  j.calendarTimeEpisode?.weatherAftercare==='external-v93.676'&&
  j.calendarTimeEpisode.weatherExposure?.some(w=>w.exposed&&
   w.id===entry.characterId&&w.proofId===entry.id)))return '';
 const proof=entry?.skillTestProof,origin=proof?.a||proof?.result;
 const skill=proof?.skills?.[0]||proof?.skill,link=entry?.calendarTrekSkillSource;
 // Never advertise weather treatment for an unrelated Endurance/Survival roll.
 const watch=data.journal.find(j=>j.id===link?.sourceId&&
  j.calendarCampaignId===entry.calendarCampaignId)?.calendarTrekProof;
 if(link?.format!=='hmk-trek-linked-skill-v1'||link.hazard!=='weather'||
  !watch?.weatherWatch?.requiresWeatherHazardRoll||
  !(watch.partyModes?.memberIds??[data.journal.find(j=>j.id===link.sourceId)?.characterId]).includes(entry.characterId)||
  !['Endurance','Survival'].includes(skill)||!origin||!['CF','F','S','CS'].includes(origin.level)||
  !['secondary-mastery-value-test','secondary-mastery-test','assistance-success-test'].includes(proof.type))return '';
 if(data.journal.some(x=>x.skillTestProof?.type==='skill-weather-onset'&&x.skillTestProof.sourceId===entry.id))return '';
 const kind=watch.weatherWatch.hazard;
 if(!['cold','heat'].includes(kind))return '';
 return `<details class="hsk-climb-fall"><summary>Trekking · ${kind==='cold'?'Cold':'Heat'} Hazard – ${esc(character(entry.characterId)?.name||'postava')} · HMK str.149,185</summary>
 <form data-skill-weather-onset><input type="hidden" name="sourceId" value="${esc(entry.id)}">
 <p>Zdroj hlídky, postava, typ počasí i původní Endurance/Survival výsledek jsou ověřené. Žádný nový d100 se nehází. GM doplní jen skutečné podmínky expozice.</p>
 <input type="hidden" name="kind" value="${esc(kind)}">
 ${kind==='cold'?`<label>Skutečné podmínky Cold Exposure<select name="coldCondition"><option value="dry">Sucho · HR5</option><option value="damp">Déšť / mokro · HR4</option><option value="coolWater">Chladná voda (vyžaduje samostatný Cold Shock)</option><option value="coldWater">Studená voda (Cold Shock)</option><option value="freezingWater">Ledová voda (Cold Shock)</option></select></label>`:''}
 <button type="submit">Zapsat doložený Weather Hazard do stavu</button><output role="status" aria-live="polite"></output>
 </form></details>`;
}
/** Confirmed S/CS Weather Hazard has no separately adjudicated health effect:
 * travel already accounted for all Fatigue. Store the original test and
 * deterministic no-effect reducer receipt atomically; never invent dice.
 */
function pendingWeatherNoEffectAftercare(){
 const clock=data.campaignClock;if(!clock)return [];
 const camp=campaignKey(clock),rows=[];
 for(const receipt of data.journal){
  const ep=receipt.calendarTimeEpisode;
  if(receipt.calendarCampaignId!==camp||ep?.weatherAftercare!=='external-v93.676'||ep.endMinute>clock.minute)continue;
  for(const w of ep.weatherExposure||[]){
   if(!w.exposed||['coolWater','coldWater','freezingWater'].includes(w.coldCondition))continue;
   const original=data.journal.find(j=>j.id===w.proofId&&j.characterId===w.id&&j.calendarCampaignId===camp);
   const level=(original?.skillTestProof?.a||original?.skillTestProof?.result)?.level;
   if(!['S','CS'].includes(level))continue;
   const sourceId=episodeWeatherAftercareId(receipt.id,w.id,w.kind);
   if(data.journal.some(j=>j.characterId===w.id&&j.skillTestProof?.type==='skill-weather-onset'&&j.skillTestProof.sourceId===sourceId))continue;
   const actor=character(w.id);
   if(actor)rows.push({receipt,w,original,level,sourceId,actor});
  }
 }
 return rows;
}
function closeWeatherNoEffectAftercare(){
 const rows=pendingWeatherNoEffectAftercare();
 for(const {receipt,w,original,level,sourceId,actor} of rows){
  // Evaluate the printed rule on an isolated neutral state. S/CS has no
  // injury or health effect; appending an event to a patient's *current*
  // health state would rewrite the chronology of a legacy/late confirmation,
  // and could block a later unrelated Shock or Coma action.
  const outcome=prepareTrekkingWeatherTest({state:initialCombatState(),sourceId,
   round:1,kind:w.kind,originalSL:level,coldCondition:w.coldCondition||'dry',
   weatherHazardConfirmed:true,fatigueAccountedExternally:true,gmConfirmed:true});
  if(outcome.report.hr!==null||outcome.report.skinPending||outcome.report.addedWeariness!==0)
   throw Error('Automatické Weather potvrzení smí mít jen nulový zdravotní následek');
  // Only the immutable calendar/journal proof is appended; do NOT modify
  // wounds, existing Shock courses, lastRound or retroactively apply fatigue.
  data.journal.push({id:uuid(),characterId:actor.id,
   calendarCampaignId:receipt.calendarCampaignId,campaignMinute:receipt.calendarTimeEpisode.endMinute,
   createdAt:stamp(),title:'Trekking '+w.kind+' Hazard · automatické potvrzení bez zdravotního následku · HMK 149',
   body:'Původní doložený výsledek '+level+'; cestovní Fatigue již byla zapsána. Žádný další hod ani rána.',
   skillTestProof:{type:'skill-weather-onset',sourceId,actorId:actor.id,report:outcome.report,
    episodeId:receipt.id,originalSkillProofId:original.id,automaticNoEffect:true}});
 }
 return rows.length;
}
function hskEpisodeWeatherOnsetForms(actorId){
 if(!data.campaignClock)return '';
 const camp=campaignKey(data.campaignClock),now=data.campaignClock.minute;
 const forms=[];
 for(const e of data.journal){
  const episode=e.calendarTimeEpisode;
  if(e.calendarCampaignId!==camp||episode?.weatherAftercare!=='external-v93.676'||
   episode.endMinute>now)continue;
  for(const w of episode.weatherExposure||[]){
   if(w.id!==actorId||w.exposed!==true)continue;
   const sourceId=episodeWeatherAftercareId(e.id,w.id,w.kind);
   if(data.journal.some(x=>x.characterId===actorId&&
    x.skillTestProof?.type==='skill-weather-onset'&&
    (x.skillTestProof.sourceId===sourceId||
     (x.skillTestProof.sourceId===w.proofId&&x.skillTestProof.report?.kind===w.kind))))continue;
   const proof=data.journal.find(x=>x.id===w.proofId&&x.characterId===actorId&&
    x.calendarCampaignId===camp);
   if(!proof||!['CF','F','S','CS'].includes((proof.skillTestProof?.a||proof.skillTestProof?.result)?.level))continue;
   // Water immersion demands an immediate one-time Shock procedure BEFORE
   // the separate Exposure outcome, regardless of the original Hazard SL.
   const water=w.kind==='cold'&&['coolWater','coldWater','freezingWater'].includes(w.coldCondition);
   if(water&&!persistentStateOf(character(actorId)).events.some(x=>x.id==='skill-cold-shock:'+sourceId)){
    forms.push(`<details class="hsk-climb-fall" open><summary>Cold Shock · skutečné ponoření · ${esc(displayCampaignMinute(episode.endMinute))} · HMK 185</summary>
    <form data-skill-cold-shock><input type="hidden" name="sourceId" value="${esc(sourceId)}"><input type="hidden" name="episodeId" value="${esc(e.id)}"><input type="hidden" name="condition" value="${esc(w.coldCondition)}">
    <p>Nejprve samostatně potvrďte skutečné 3d6 kol ponoření a nový Endurance d100. Původní Weather Hazard Endurance/Survival se neopakuje. Podmínky ${esc(w.coldCondition)}.</p>
    <div class="field-grid">${[1,2,3].map(i=>`<label>d6 č. ${i}<input name="d6_${i}" type="number" min="1" max="6" required></label>`).join('')}
    <label>Cold Shock Endurance d100<input name="enduranceD100" type="number" min="1" max="100" required></label></div>
    <button type="submit">Vyhodnotit a uložit Cold Shock</button><output role="status" aria-live="polite"></output></form></details>`);
    continue;
   }
   forms.push(`<details class="hsk-climb-fall"><summary>${w.kind==='cold'?'Cold':'Heat'} Hazard – zdravotní následek v ${esc(displayCampaignMinute(episode.endMinute))} · HMK 149,185</summary>
    <form data-skill-weather-onset><input type="hidden" name="sourceId" value="${esc(sourceId)}"><input type="hidden" name="episodeId" value="${esc(e.id)}"><input type="hidden" name="kind" value="${esc(w.kind)}">
    <p>Původní Endurance/Survival má výsledek ${esc((proof.skillTestProof.a||proof.skillTestProof.result).level)}. Je již interně propojen se správnou postavou, minutou a původním dokladem; tento hod se neopakuje. Cestovní Fatigue je již započtená; zde se potvrdí pouze samostatný zdravotní následek.</p>
    <p>Skutečné podmínky Cold Hazard: ${esc(w.coldCondition||'dry')}. Původní identifikátor expozice zůstává bezpečně uložen v deníku.</p>
    <button type="submit">Potvrdit zdravotní následek Weather Hazard</button><output role="status" aria-live="polite"></output></form></details>`);
  }
 }
 return forms.join('');
}
