function hskTrekkingWeatherTreatmentForms(actorId){
 const actor=character(actorId);if(!actor)return '';
 const clock=data.campaignClock;
 return (persistentStateOf(actor).environmentalHazards||[]).filter(h=>h.active&&!h.treatmentStarted).map(h=>{
  const origin=clock?getCampaignEpisodeAnchor(clock,'weather',actor.id,h.id):null;
  const ready=!!clock&&!!origin&&clock.minute>=origin.minute;
  const kind=h.kind==='cold';
  const treatment=kind?'Warming':'Compress';
  const due=clock?campaignCalendarAgenda(clock,data.characters,data.journal,data.inventory).all.find(x=>x.kind==='weather-course'&&x.characterId===actor.id&&x.sourceId===h.sourceId):null;
  return `<details class="hsk-climb-fall hsk-exposure-card"><summary>Zahájit ${treatment} · ${kind?'Cold':'Heat'} Exposure · HMK 185</summary>
   <form data-skill-weather-treatment><input type="hidden" name="sourceId" value="${esc(h.sourceId)}">
   <p class="hc-hint">${esc(displayCampaignMinute(clock?.minute??0))} · Tento krok není další Course hod. GM může zahájit léčbu, jakmile postava skutečně opustí nebezpečné podmínky; počátek a další termíny určí Kalendář.</p>
   ${due&&due.minute===clock?.minute?'<p class="hc-hint">Ve stejné minutě je také splatný Exposure Advance. Potvrzením tohoto tlačítka GM volí nejprve zahájení léčby; alternativně lze nejdřív provést splatný Course.</p>':''}
   <div class="hsk-exposure-choice" data-hmk-help="${esc(HSK_EXPOSURE_HELP_93726.removed)}" tabindex="0">
    <label class="hsk-exposure-check"><input name="removedFromHazard" type="checkbox" required> <span><strong>Skutečně vyvedeno z ${kind?'chladu a vody':'přímého slunce'}</strong><small>GM potvrdí změnu prostředí; bez ní nelze zahájit Healing.</small></span></label>
   </div>
   ${kind?'':`<div class="hsk-exposure-choice" data-hmk-help="${esc(HSK_EXPOSURE_HELP_93726.water)}" tabindex="0"><label class="hsk-exposure-check"><input name="coolWater" type="checkbox"><span><strong>Compress s chlazením chladnou vodou</strong><small>Skutečné chlazení: kontrola po 5 místo 15 minutách.</small></span></label></div>`}
   <p class="hc-hint" data-hmk-help="${esc(kind?HSK_EXPOSURE_HELP_93726.warming:HSK_EXPOSURE_HELP_93726.compress)}" tabindex="0">${kind?'Warming: HB × 5 jednou za 120 minut.':'Compress: HB × 5 každých 15 minut, nebo každých 5 při skutečném chlazení vodou.'}</p>
   <button type="submit" ${ready?'':'disabled'} data-hmk-help="${esc(HSK_EXPOSURE_HELP_93726.start)}">Zahájit ${treatment} v aktuální minutě</button>
   ${!ready?'<p class="hc-hint">Chybí platná kalendářová kotva této expozice; čas nelze domýšlet.</p>':''}
   <output role="status" aria-live="polite"></output></form></details>`;
 }).join('');
}
function hskTrekkingWeatherCourseForms(actorId){
 const actor=character(actorId);if(!actor)return '';
 const state=persistentStateOf(actor),active=(state.environmentalHazards||[]).filter(x=>x.active);
 const clock=data.campaignClock;
 const agenda=clock?campaignCalendarAgenda(clock,data.characters,data.journal,data.inventory):null;
 return active.map(h=>{
  const due=agenda?.all.find(x=>x.kind==='weather-course'&&x.characterId===actor.id&&x.sourceId===h.sourceId)||null;
  const origin=clock?getCampaignEpisodeAnchor(clock,'weather',actor.id,h.id):null;
  const elapsedActual=origin&&clock?clock.minute-origin.minute:null;
  const ready=!!clock&&!!due&&due.minute===clock.minute;
  const method=h.treatmentStarted?'healing':'advance';
  const methodLabel=h.treatmentStarted?'Exposure Healing':'Exposure Advance';
  const period=h.treatmentStarted?h.healingIntervalMinutes:h.periodMinutes;
  const label=h.kind==='cold'?'Cold':'Heat';
  return `<details class="hsk-climb-fall hsk-exposure-card" ${ready?'open':''}><summary>${label} Exposure · HR${h.hr} · ${ready?'splatný '+methodLabel:'následující kontrola'} · HMK 185</summary>
   <p class="hc-hint">Aktivní ${label} Exposure. ${h.treatmentStarted?'Warming/Compress byl zahájen a platí režim Healing.':'Nebylo zahájeno Warming/Compress: stále platí původní Exposure Advance.'} ${h.skinPending?'<strong>Ještě je třeba vyřešit '+esc(h.skinPending)+' v anatomickém formuláři.</strong>':''}</p>
   <div class="hsk-exposure-readout">
    <div data-hmk-help="${esc(HSK_EXPOSURE_HELP_93726.method)}" tabindex="0"><span>Pravidlový postup</span><strong>${methodLabel}</strong></div>
    <div data-hmk-help="${esc(HSK_EXPOSURE_HELP_93726.elapsed)}" tabindex="0"><span>Skutečně uběhlý čas (Kalendář)</span><strong>${elapsedActual===null?'Neověřeno':elapsedActual+' minut'}</strong></div>
    <div data-hmk-help="${esc(HSK_EXPOSURE_HELP_93726.die)}" tabindex="0"><span>Další kontrola d100</span><strong>${due?esc(displayCampaignMinute(due.minute)):'Chybí časová kotva'}</strong></div>
    <div tabindex="0" data-hmk-help="${esc(HSK_EXPOSURE_HELP_93726.method)}"><span>Pravidlový interval</span><strong>${Number.isInteger(period)?period+' minut':'Neověřeno'}</strong></div>
   </div>
   ${ready?`<form data-skill-weather-course><input type="hidden" name="sourceId" value="${esc(h.sourceId)}"><input type="hidden" name="method" value="${method}">
    <p class="hc-hint">Nyní je splatná právě tato kontrola. Skutečné minuty i režim jsou převzaty z Kalendáře a nelze je měnit. ${h.treatmentStarted?'Vyvedení z nebezpečí a případné chlazení už bylo potvrzeno při zahájení léčby.':'Pro Advance není potřeba zaškrtávat vyvedení ani chlazení.'}</p>
    <div class="hsk-exposure-roll-row"><label data-hmk-help="${esc(HSK_EXPOSURE_HELP_93726.die)}" tabindex="0">Nový skutečný ${methodLabel} d100<input type="number" name="roll" min="1" max="100" inputmode="numeric" required></label>
    <button type="submit" data-hmk-help="${esc(HSK_EXPOSURE_HELP_93726.course)}">Vyhodnotit právě splatný d100</button></div>
    <output role="status" aria-live="polite"></output></form>`:
    `<p class="hsk-exposure-wait" role="status">${due&&clock&&due.minute>clock.minute?'Další hod ještě není splatný. Před tímto termínem není možné zadávat kostku ani vytvářet další Course.':due&&clock&&due.minute<clock.minute?'Termín již uplynul; je potřeba zkontrolovat časovou osu, nelze zpětně vymyslet hod.':'Nejdříve musí být doložena časová kotva v Kalendáři.'}</p>`}
   </details>`;
 }).join('');
}
/** Environmental medical continuations have a dedicated Health/Exposure
 * chapter. They still use the EXACT original Skill/Calendar/CombatState
 * executors and IDs: there is no second health ledger or duplicate write. */
/** A weather injury is physically the same HMK wound as one from combat,
 * but its medical follow-ups live in Health & Exposure. This is only a
 * presentation of the original Injury/Treatment executor and shared ledger. */
function hskIsEnvironmentalWound(actor,woundId){
 return !!actor&&persistentStateOf(actor).wounds.some(w=>w.id===woundId&&
  isNoncombatMedicalOrigin(medicalOriginOfWound(w,persistentStateOf(actor).events)));
}
/** Travel does not begin an encounter to resolve bodily injury consequences.
 * A Weather injury's next required action is rendered here in the Health tab.
 * One actor + one original wound/mishap ID + one d100 at a time. */
function hskWeatherInjuryMandatory(actorId){
 const actor=character(actorId);if(!actor)return '';
 const state=persistentStateOf(actor),isWeather=id=>hskIsEnvironmentalWound(actor,id);
 const m=unresolvedInjuryMishaps(state).find(x=>isWeather(x.woundId));
 if(m){
  const automatic=m.kind.startsWith('automatic-'),attributes=actor.hmk?.attributes||{};
  return `<section class="panel wide hmk-weather-injury-mandatory"><h3>Cestovní Injury Mishap · ${esc(actor.name)}</h3>
  <p class="hc-hint">Povinný následek skutečné rány z počasí (HMK 170). Žádný bojový útok ani tah se nespouští. Rána ${esc(m.woundId)} · ${esc(m.kind)}. Vyhodnoťte pouze tuto povinnost a potvrďte GM.</p>
  <form data-weather-injury-mishap><input type="hidden" name="mishapId" value="${esc(m.id)}">
  <label>Jaká skutečná činnost byla narušena?<select name="test"><option value="agility">Agility (${esc(String(attributes.agl??'?'))} × 5)</option>${Number.isSafeInteger(attributes.dex)?`<option value="dexterity">Dexterity (${attributes.dex} × 5), pouze pokud GM potvrdí činnost vyžadující DEX</option>`:''}${(actor.hmk?.skills||[]).filter(x=>['acrobatics','legerdemain'].includes(String(x.name).toLowerCase())).map(x=>`<option value="${esc(x.name.toLowerCase())}">${esc(x.name)} · ML ${x.ml}</option>`).join('')}</select></label>
  ${automatic?'<p>Automatický Mishap: podle tabulky se další d100 nehází.</p>':'<label>Skutečný d100<input name="roll" type="number" min="1" max="100" required></label>'}
  <button type="submit">Dokončit jediný cestovní Injury Mishap</button><output role="status"></output></form></section>`;
 }
 const morale=dueInjuryMorale(state).find(x=>isWeather(x.woundId));
 if(morale){
  const w=state.wounds.find(x=>x.id===morale.woundId);
  const init=actor.hmk?.skills?.find(x=>String(x.name||'').toLowerCase()==='initiative')?.ml;
  return `<section class="panel wide hmk-weather-injury-mandatory"><h3>Cestovní Injury Morale · ${esc(actor.name)}</h3>
  <p class="hc-hint">Až po úplném Shock zotavení: jediný Morale d100 z vážné rány ${esc(w.id)} (HMK 162, 170). Bez aktivního Combatu; případný skutečný zdroj Aberrance stanoví GM.</p>
  <form data-weather-injury-morale><input type="hidden" name="woundId" value="${esc(w.id)}">
  <p>Initiative ML: ${esc(String(init??'nedoloženo'))}</p>
  <label>Skutečná Aberrance zdroje (0 jen po výslovném potvrzení GM)<input name="aberrance" type="number" min="0" max="200" ${Number.isSafeInteger(w.moraleThreatABE)?`value="${w.moraleThreatABE}" readonly`:''} required></label>
  <label>Skutečný Morale d100<input name="roll" type="number" min="1" max="100" required></label>
  <button type="submit" ${Number.isSafeInteger(init)?'':'disabled'}>Dokončit jediný cestovní Injury Morale</button><output role="status"></output></form></section>`;
 }
 return '';
}
/** Weather Bleeding belongs to Health/Exposure; never call the Combat
 * Stoppage form or infer 60 combat rounds from an elapsed calendar interval.
 * One five-minute plan, one due physical Physician/Strength roll, one write. */
function hskWeatherBleedingCarePanel(actorId){
 const helpTerm=(label,text)=>`<span class="hc-help-term" tabindex="0" data-hmk-help="${esc(text)}">${label}</span>`;
 const actor=character(actorId),clock=data.campaignClock;
 if(!actor||!clock)return '';
 const state=persistentStateOf(actor),wounds=state.wounds.filter(w=>isNoncombatMedicalOrigin(medicalOriginOfWound(w,state.events))&&w.bleeding&&!w.healed);
 if(!wounds.length)return '';
 const party=calendarMemberIds(clock,data.characters);
 const items=wounds.map(w=>{
  let term;
  try{term=travelBleedingTerm({clock,actorId:actor.id,wound:w,state});}
  catch(error){return `<p class="notice">${esc(w.id)} · Blood Stoppage nelze zatím otevřít: ${esc(error.message)}</p>`;}
  const due=clock.minute===term.dueMinute,remaining=term.dueMinute-clock.minute;
  const plan=term.plan;
  const who=plan?party.find(c=>c.id===plan.healerId):null;
  const healerOptions=weatherPhysicianCandidates({patient:actor,wound:w,party});
  const start=remaining===5&&!plan;
  const title=`${esc(w.location)} ${esc(w.severity+w.level)} · ${esc(w.id)}`;
  const head=`<h4>Blood Stoppage · ${title}</h4><p class="hc-hint">Původ ${esc(displayCampaignMinute(term.anchorMinute))} ·
   příští povinný interval ${esc(displayCampaignMinute(term.dueMinute))} ·
   ${plan?`probíhá 5minutové ${plan.method==='cau'?'Cauterisation':'Staunch'} u ${esc(who?.name||plan.healerId)}`:
    'bez zahájeného ošetření'}.
   Každých 5 minut jeden Blood Loss na každého Bleedera; po skutečném Blood Stoppage výsledku CF/F/S ještě Blood Loss, po CS nikoliv (HMK 178).</p>`;
  if(start){return `<article class="hc-calendar-linked-row">${head}
   <form data-weather-blood-start class="hc-fields"><input type="hidden" name="woundId" value="${esc(w.id)}">
   <div class="field-grid"><label>${helpTerm('Skutečný léčitel','Vyberte živého, schopného Physician z aktuální kampaně. Tato volba zaznamená začátek skutečného pětiminutového úkonu, ne provedený hod.')}
   <select name="healerId" required><option value="">Vyberte léčitele…</option>${healerOptions.map(h=>`<option value="${esc(h.id)}">${esc(h.name)} · Physician ML ${h.ml}${h.self?' · self':''}</option>`).join('')}</select></label>
   <label>${helpTerm('Treatment','Staunch (sta) se provádí tlakem s obvazem a vodou; Cauterisation (cau) vyžaduje rozžhavený kov a dává +30 EML, ale ovlivňuje následné hojení.')}
   <select name="method"><option value="sta">Staunch · 5 minut</option><option value="cau">Cauterisation · 5 minut (+30)</option></select></label>
   </div><p class="hc-hint">Počet souběžných ran ošetřených stejným léčitelem se ověří z potvrzených začátků v celé kampani (−10 za každou další ránu).</p>
   <div class="field-grid"><label>Staunch · skutečné d6 na každý Bloodloss Point (${state.bloodLoss.bp} BP; ${state.bloodLoss.bp===0?'automaticky 1 obvaz':state.bloodLoss.bp+' hodnot oddělených čárkou'})<input name="bandageD6Rolls" placeholder="${state.bloodLoss.bp===0?'BP 0 → 1 obvaz':'např. 2,4'}" ${state.bloodLoss.bp>0?'':''}></label>
   <label><input type="checkbox" name="hasWater"> Voda pro Clean & Dress</label>
   <label><input type="checkbox" name="hasNeedleThread"> Jehla a nit pro Serious Edge/Point</label>
   <label><input type="checkbox" name="hasHeatedTool"> Rozžhavený kovový nástroj pro Cauterisation</label>
   <label><input type="checkbox" name="tourniquet"> Turniket (pouze končetina, Staunch +20)</label></div>
   <button type="submit" ${healerOptions.length?'':'disabled'}>Zahájit 5minutové ošetření</button>
   <p class="tiny">D100 se zatím nehází. Kalendář se sám neposune; GM jej posune na vyznačený konec ošetření.</p>
   </form></article>`;}
  if(due){return `<article class="hc-calendar-linked-row">${head}
   <form data-weather-blood-complete class="hc-fields"><input type="hidden" name="woundId" value="${esc(w.id)}">
   <input type="hidden" name="mode" value="${plan?'stoppage':'loss'}">
   ${plan?`<p>Potvrzený léčitel: <strong>${esc(who?.name||plan.healerId)}</strong> · ${esc(plan.method)}
    · 5 minut skutečně uplynulo.</p>
    <label>${helpTerm('Physician d100','Skutečný hod léčitele, EML vypočítá systém z Physician ML, Fatigue, metody, případného předchozího bonusu a počtu současně ošetřených ran.')}
    <input type="number" name="physicianRoll" min="1" max="100" required></label>`:
    '<p>V předchozím intervalu nebylo zahájeno doložené ošetření. Vyhodnoťte pouze Blood Loss.</p>'}
   <label>${helpTerm('Blood Loss · Strength d100','Povinný jeden skutečný hod pacienta proti Strength ×5 bez Fatigue a impairment. Po Critical Success (CS) u Physician ponechte prázdné; po CF/F/S jej vyplňte.')}
   <input type="number" name="strengthRoll" min="1" max="100" ${plan?'':'required'}></label>
   <button type="submit">${plan?'Zapsat Blood Stoppage + případný Blood Loss':'Zapsat Blood Loss Advance'}</button>
   </form></article>`;}
  return `<article class="hc-calendar-linked-row">${head}<p class="hc-hint">${remaining>0?
   `Do splatnosti zbývá ${remaining} minut. ${plan?'Dokončete kalendářem skutečných 5 minut.':'Ošetření již nelze zpětně zahájit. V termínu proběhne Blood Loss.'}`:
   'Splatný interval je po termínu; kalendář musí být nejprve uveden do souladu s pravidlovou povinností.'}</p></article>`;
 }).join('');
 return `<section class="panel wide hmk-weather-blood-care"><h3>Blood Stoppage · cestovní zdravotní postup · ${esc(actor.name)}</h3>
 <p class="hc-hint">Aktivní krvácení je přednostní před běžným Treatment/Healing. Celkové Blood Loss Points jsou ${state.bloodLoss.bp}/4,
 Weakness ${state.bloodLoss.weaknessFatigue}. Bez vstupu do Combatu, bez fiktivních hodů či okamžitého 5minutového skoku.</p>${items}</section>`;
}
function hskEnvironmentalWoundCarePanel(actor){
 const pending=persistentStateOf(actor).wounds.some(w=>!w.healed&&isNoncombatMedicalOrigin(medicalOriginOfWound(w,persistentStateOf(actor).events)));
 if(!pending)return '';
 if(persistentStateOf(actor).wounds.some(w=>w.bleeding&&isNoncombatMedicalOrigin(medicalOriginOfWound(w,persistentStateOf(actor).events))))
  return '<p class="notice">Před dalším Treatment nebo Healing nejprve uzavřete Blood Stoppage v Zdraví & Expozice.</p>';
 if(persistentStateOf(actor).extendedShock)
  return '<p class="notice">Treatment není nyní dostupný: nejprve musí skončit Extended Shock podle čtyřhodinových Course Rolls (HMK 179). Kalendář zachovává čas dalšího Course.</p>';
 if(unresolvedInjuryMishaps(persistentStateOf(actor)).some(m=>hskIsEnvironmentalWound(actor,m.woundId)))
  return '<p class="notice">Před rozhodnutím o Treatment dokončete bezprostřední Injury Mishap. Shock Reroll má vlastní skutečný kalendářní termín; nesmí blokovat ošetření jinou způsobilou postavou ani výslovné GM rozhodnutí ponechat ránu neošetřenou.</p>';
 return `<details class="hmk-weather-wound-care" open><summary>Rány z cestování a počasí · Treatment, Healing, Infection Course a případná amputace</summary>
 <p class="hc-hint">Povinné ošetření nové Frostbite/Sunburn rány je samostatný zdravotní krok. Používá původní společný HMK Treatment/Healing/Infection executor a nemění čas bez potvrzení GM.</p>
 ${hmkLongtermHealingPanel([actor],{origin:'noncombat'})}</details>`;
}
/** Weather Shock is a distinct original procedure with its own calendar
 * minute, actor and immutable source ID. Combat still sees resulting fatigue,
 * wounds and Shock, but cannot create a second Weather roll. */
/** Shock ML is read from the live actor if explicitly registered. For a
 * registered mount without an individual entry, HMK p.355 supplies the
 * original printed breed Shock ML. Never guess for an unknown animal. */
function hskVerifiedNoncombatShockML(actor){
 if(!actor)return null;
 const live=availableMasteries(actor).filter(x=>x.name==='Shock');
 if(live.length>1)return null; // conflicting authoritative entries
 if(live.length===1)return Number.isSafeInteger(live[0].ml)&&live[0].ml>0?live[0].ml:null;
 const printed=verifiedMountedShockML(actor);
 return Number.isSafeInteger(printed)&&printed>0?printed:null;
}
function hskWeatherShockFollowup(actorId){
 const actor=character(actorId),state=actor&&persistentStateOf(actor),q=state?.shockFollowup;
 if(!q||!isNoncombatMedicalOrigin(q.domain))return '';
 const clock=data.campaignClock,minute=clock?.minute;
 const dueMinute=q.phase==='after-all-bleeding-stopped'?q.originMinute:q.kind==='UNC'?q.originMinute+10:q.originMinute;
 const shockML=hskVerifiedNoncombatShockML(actor);
 const canRoll=Number.isSafeInteger(minute)&&minute>=dueMinute&&Number.isSafeInteger(shockML);
 const fatigue=combatFatigueTotals(state).total,eml=Number(shockML)-fatigue-(q.kind==='STN'?0:20);
 const comaCause=verifiedNoncombatComaCause({actor,state,shockFollowup:q});
 return `<section class="panel wide hmk-weather-shock-followup"><h3>${q.domain==='travel-accident'?'Accident':'Weather'} Shock · ${esc(actor.name)} · ${esc(q.kind)}</h3>
 <p class="hc-hint">Samostatný Shock Reroll z cestování (${esc(q.sourceId)}). Původ ${esc(displayCampaignMinute(q.originMinute))}. ${q.phase==='after-all-bleeding-stopped'?'Okamžitý Shock Reroll po zastavení všech Bleederů':q.kind==='UNC'?'Počkat skutečných 10 minut':'Po další skutečné akci mimo boj vyhodnoť tento hod'}. Kalendář je autoritou pro minuty; tento hod jej sám neposune. Combat pouze čte účinky na postavu (HMK 169, 185).</p>
 <p>Shock ML ${esc(String(shockML??'nedoloženo'))} · Fatigue ${fatigue} · ${q.kind==='STN'?'bez dalšího −20':'−20 při INC/UNC'} · EML ${esc(String(Number.isInteger(shockML)?eml:'nedoloženo'))}</p>
 <form data-weather-shock-followup data-shock-eml="${esc(String(Number.isFinite(eml)?eml:''))}" data-shock-coma-ready="${comaCause.ready&&canRoll?'yes':'no'}"><input type="hidden" name="sourceId" value="${esc(q.sourceId)}">
 <label>Skutečný Shock d100<input name="roll" type="number" min="1" max="100" required ${canRoll?'':'disabled title="Shock ještě není splatný nebo chybí ověřená ML"'}></label>
 ${q.kind==='UNC'?`<p class="hc-hint">${comaCause.ready?'Coma při CF: původní rána '+esc(comaCause.woundId)+' · ověřené Location Shock '+comaCause.locationShock+' · IL '+comaCause.injuryLevel+' · počáteční HR '+comaCause.initialHR+'. Hodnoty nejsou upravitelné.':'Coma při CF: '+esc(comaCause.reason)}</p><input name="comaLocationShock" type="hidden" value="${comaCause.ready?comaCause.locationShock:''}"><input name="comaInjuryLevel" type="hidden" value="${comaCause.ready?comaCause.injuryLevel:''}"><label>První skutečný d10 dní do Coma Course<input name="initialComaD10" type="number" min="1" max="10" required disabled title="Coma d10 je dostupné pouze po skutečném výsledku UNC + CF"><button type="button" class="hc-small" data-weather-coma-d10 disabled title="Vygenerovat skutečný d10 (bez potvrzení akce)">⚄ d10</button></label>`:''}
 <p class="hc-hint">${q.phase==='after-all-bleeding-stopped'?'Ihned po zastavení všech Bleederů – bez dalších deseti minut.':q.kind==='UNC'?'Test je dostupný přesně po uplynutí deseti minut.':'Tlačítko vyhodnotí Shock po dokončení následující skutečné akce postavy; žádný bojový tah se nevytváří.'}</p>
 ${q.kind!=='UNC'&&q.phase!=='after-all-bleeding-stopped'?'<label><input type="checkbox" name="actualActionConfirmed" required '+(canRoll?'':'disabled')+'> GM potvrzuje skutečnou následující akci mimo boj, na jejímž konci probíhá Shock Reroll</label>':''}
 <button type="submit" ${canRoll?'':'disabled'}>Vyhodnotit a zapsat Shock d100</button><output role="status" aria-live="polite"></output></form>
 ${!canRoll?'<p class="notice">Zatím nesplatné nebo postava nemá doložené Shock ML.</p>':''}</section>`;
}
/** Source-keyed immersion follow-ups never replace an earlier Extended
 * Shock/Coma and never need Combat to open an auxiliary procedure. */
function hskParallelColdHealthPanel(actorId){
 const actor=character(actorId),clock=data.campaignClock;
 if(!actor||!clock)return '';
 const s=persistentStateOf(actor),rows=s.parallelColdShocks??[];
 return rows.filter(x=>x.followup||x.extendedShock||x.coma?.active).map(x=>{
  const items=[];
  if(x.followup){
   const due=x.followup.dueMinute,ml=availableMasteries(actor).find(z=>z.name==='Shock')?.ml;
   const eml=Number(ml)-combatFatigueTotals(s).total-(x.shock==='STN'?0:20);
   const rerollReady=clock.minute>=due&&Number.isInteger(ml);
   items.push(`<form data-parallel-cold-reroll><input type="hidden" name="sourceId" value="${esc(x.sourceId)}">
    <h4>Cold Water Shock Reroll · ${esc(x.sourceId)}</h4>
    <p class="hc-hint">Původní Shock ${esc(x.shock)}, termín ${esc(displayCampaignMinute(due))}; žádný další bojový krok ani časový posun se nevytváří. Původní Extended Shock/Coma běží nezávisle.</p>
    <p>Shock ML ${esc(String(ml??'neznámá'))} · EML ${esc(String(Number.isInteger(ml)?eml:'neznámá'))}.</p>
    <label>Skutečný Shock d100<input name="roll" type="number" min="1" max="100" required ${rerollReady?'':'disabled'}></label>
    ${x.shock==='UNC'?`<label>Jen při UNC+CF: GM výslovně určený Coma HR pro ponoření bez Injury Level<input name="initialComaHR" type="number" min="1" max="20" ${rerollReady?'':'disabled'}></label><label>Jen při UNC+CF: první skutečný Coma d10 dní<input name="initialComaD10" type="number" min="1" max="10" ${rerollReady?'':'disabled'}></label>`:''}
    <button type="submit" ${rerollReady?'':'disabled'}>Zapsat samostatný Shock Reroll</button><output role="status" aria-live="polite"></output></form>`);
  }
  for(const kind of ['extended-shock','coma']){
   const c=kind==='extended-shock'?x.extendedShock:x.coma?.active?x.coma:null;
   if(!c)continue;
   const due=kind==='extended-shock'?c.startMinute+(c.elapsedHours+4)*60:c.startMinute+(c.elapsedDays+c.nextCourseDays)*DAY_MINUTES;
   const courseReady=clock.minute===due;
   items.push(`<form data-parallel-cold-course><input type="hidden" name="sourceId" value="${esc(x.sourceId)}"><input type="hidden" name="kind" value="${kind}">
    <h4>${kind==='extended-shock'?'Extended Shock':'Coma'} · samostatný Cold Water Course</h4>
    <p class="hc-hint">Zdroj ${esc(x.sourceId)} · HR${c.hr} · pravidlový termín ${esc(displayCampaignMinute(due))} · aktuální minuta ${esc(displayCampaignMinute(clock.minute))}.</p>
    <label>Skutečný Course d100<input name="roll" type="number" min="1" max="100" required ${courseReady?'':'disabled'}></label>
    ${kind==='extended-shock'?`<label>Nejvyšší skutečné Physician SV hvězdy<input name="physicianStars" type="number" min="0" max="10" value="0" required ${courseReady?'':'disabled'}></label>`:`<label>Klidné chráněné prostředí<select name="restfulShelter" ${courseReady?'':'disabled'}><option value="yes">Ano</option><option value="no">Ne (−20)</option></select></label><label>Nový skutečný d10, pouze pokud Coma pokračuje<input name="nextComaD10" type="number" min="1" max="10" ${courseReady?'':'disabled'}></label>`}
    <label>Doložený Arcane bonus<input name="arcaneBonus" type="number" min="0" max="100" value="0" required ${courseReady?'':'disabled'}></label>
    <button type="submit" ${courseReady?'':'disabled'}>Zapsat právě splatný Course</button><output role="status" aria-live="polite"></output></form>`);
  }
  return `<section class="panel wide hmk-parallel-cold-course"><h3>Cold Water Shock · souběžná zdravotní událost · ${esc(actor.name)}</h3>${items.join('')}</section>`;
 }).join('');
}
/** Health owns time-bound Weather Extended Shock and Coma. Only one
 * due Course, one actor and one d100 are offered. The original HMK p.179
 * executor remains authoritative; Combat is never started by Travel. */
function hskWeatherTraumaCourseKind(actor,kind){
 const s=actor&&persistentStateOf(actor);
 return !!s&&((kind==='extended-shock'&&isNoncombatMedicalOrigin(s.extendedShock?.domain))||
  (kind==='coma'&&s.coma?.active&&isNoncombatMedicalOrigin(s.coma.domain))||
  (s.parallelColdShocks??[]).some(x=>kind==='extended-shock'?!!x.extendedShock:kind==='coma'&&x.coma?.active));
}
function hskWeatherTraumaCourseForm(actorId){
 const actor=character(actorId),clock=data.campaignClock;
 if(!actor||!clock)return '';
 const agenda=campaignCalendarAgenda(clock,data.characters,data.journal,data.inventory);
 const health=persistentStateOf(actor);
 const due=agenda.due.filter(x=>x.characterId===actorId&&['extended-shock','coma'].includes(x.kind)&&
  !x.sourceId&&((x.kind==='extended-shock'&&isNoncombatMedicalOrigin(health.extendedShock?.domain))||
  (x.kind==='coma'&&health.coma?.active&&isNoncombatMedicalOrigin(health.coma.domain)))).sort((a,b)=>a.minute-b.minute||
  (a.kind==='extended-shock'?-1:1))[0];
 if(!due)return '';
 const kind=due.kind,state=persistentStateOf(actor),course=kind==='extended-shock'?state.extendedShock:state.coma;
 const anchor=getCampaignAnchor(clock,kind,actor.id);
 if(!anchor)return '<p class="notice error">Weather '+esc(kind)+': chybí původní časová kotva. Nepřesouvejte tuto událost do Combatu.</p>';
 const expected=anchor.minute+(kind==='extended-shock'?(state.extendedShock.elapsedHours+4)*60:
  (state.coma.elapsedDays+state.coma.nextCourseDays)*DAY_MINUTES);
 if(clock.minute!==expected)return '<p class="notice error">Weather '+esc(kind)+': termín '+esc(displayCampaignMinute(expected))+
  ' neodpovídá aktuálnímu času. Žádný dodatečný hod se nevytváří.</p>';
 let hb;
 try{hb=guidedTraumaCourseReadiness({state,character:actor,kind}).healingBase;}
 catch(error){return '<p class="notice error">'+esc(error.message)+'</p>';}
 return `<section class="panel wide hmk-weather-trauma-course"><h3>${kind==='coma'?'Coma':'Extended Shock'} · ${esc(actor.name)}</h3>
 <p class="hc-hint">Samostatné zdravotní vyhodnocení z počasí · HMK str.179. Původní zdroj ${esc(course.sourceId)}.
 Doložený termín ${esc(displayCampaignMinute(expected))}; Kalendář se tímto hodem neposouvá.</p>
 <p>Healing Base ${hb} · aktuální HR ${course.hr} · skutečná minuta ${esc(String(clock.minute))}.</p>
 <form data-weather-trauma-course><input type="hidden" name="kind" value="${kind}">
 <input type="hidden" name="sourceId" value="${esc(course.sourceId)}">
 <label>Skutečný Course d100<input name="roll" type="number" min="1" max="100" required></label>
 ${kind==='extended-shock'?'<label>Skutečný Physician SV – počet hvězd (0 bez ošetření)<input name="physicianStars" type="number" min="0" max="10" value="0" required></label>':
 '<label>Klidné chráněné prostředí<select name="restfulShelter"><option value="yes">Ano</option><option value="no">Ne (−20)</option></select></label><label>Nový skutečný d10 pouze pokud Coma pokračuje<input name="periodD10" type="number" min="1" max="10" placeholder="Nevyplňovat při ukončení"></label>'}
 <label>Doložený Arcane Recovery bonus (0 pokud není)<input name="arcaneBonus" type="number" min="0" max="100" value="0" required></label>
 <button type="submit">Dokončit jediný ${kind==='coma'?'Coma':'Extended Shock'} Course</button>
 <output role="status" aria-live="polite"></output></form></section>`;
}
let hskWeatherHealthLastReceipt=null;
function hskWeatherHealthConsequences(actorId){
 const entries=data.journal.filter(x=>x.characterId===actorId);
 const success=hskWeatherHealthLastReceipt?.actorId===actorId?
  `<p class="hc-health-result" role="status" aria-live="polite">${esc(hskWeatherHealthLastReceipt.message)}</p>`:'';
 const weatherBlood=hskWeatherBleedingCarePanel(actorId);
 const weatherShock=hskWeatherShockFollowup(actorId);
 const parallel=hskParallelColdHealthPanel(actorId);
 if(weatherBlood)return success+parallel+weatherBlood+(weatherShock||'')+hskWeatherInjuryMandatory(actorId);
 // One current compulsory health test per actor; no new Cold/Heat dice while
 // a prior weather-induced Shock reroll remains unresolved.
 if(weatherShock)return success+parallel+(hskWeatherInjuryMandatory(actorId)||'')+weatherShock;
 const trauma=hskWeatherTraumaCourseForm(actorId);
 if(trauma)return success+parallel+trauma;
 const injuryMandatory=hskWeatherInjuryMandatory(actorId);
 if(injuryMandatory)return success+parallel+injuryMandatory;
 const html=entries.map(x=>hskTrekkingWeatherForm(x)+hskTrekkingColdShockForm(x)).join('')+
  hskEpisodeWeatherOnsetForms(actorId)+hskTrekkingWeatherTreatmentForms(actorId)+
  hskTrekkingWeatherCourseForms(actorId)+hskTrekkingSkinForms(actorId);
 return success+parallel+(html?'<section class="panel wide hmk-health-exposure-followups"><h3>Počasí · zdravotní vyhodnocení HMK 149, 185</h3><p class="hc-hint">Každý jednotlivý hod má původní ID a pravidlový termín. Po uložení aplikace sama vybere další splatnou povinnost; další potvrzovací checkbox není třeba. Combat pouze čte trvalý zdravotní stav.</p>'+html+'</section>':'');
}
function hskPendingSkillPhysicalConsequences(actorId,{includeWeather=true}={}){
 const pending=data.journal.filter(x=>x.skillTestProof?.type==='critical-followup'&&
  x.skillTestProof.actorId===actorId&&
  !data.journal.some(j=>['climbing-falling','skill-physical-consequence'].includes(j.skillTestProof?.type)&&j.skillTestProof.sourceId===x.id));
 const unresolved=data.journal.filter(x=>x.skillTestProof&&
  (x.characterId===actorId||x.skillTestProof.opponentId===actorId)&&
  !['critical-followup','climbing-falling','skill-physical-consequence','special-secondary-roll'].includes(x.skillTestProof.type));
 const originalForms=unresolved.map(x=>hskCriticalNextHTML(x.id,x.skillTestProof,{actorId})+hskBalanceNervesHTML(x.id,x.skillTestProof,{actorId})).join('');
 const confirmedAccidents=data.journal.filter(x=>x.characterId===actorId&&
  x.calendarEpisodeSkillLink?.field==='orientationProofId'&&
  data.journal.some(j=>j.calendarCampaignId===x.calendarCampaignId&&
   j.calendarTimeEpisode?.orientation?.skillId===x.id&&
   j.calendarTimeEpisode.hazardDetails?.some(h=>h.hazard==='accident'&&h.externalMedicalPending)));
 const html=originalForms+pending.map(x=>hskClimbingFallForm(x)+hskFishingGearForm(x)+hskSkillPhysicalImpactForm(x)).join('')+
  confirmedAccidents.map(x=>hskSkillPhysicalImpactForm(x)).join('')+
  data.journal.filter(x=>x.characterId===actorId).map(x=>hskSkillEnvironmentFollowup(x)+hskSeriousAggravationForm(x)).join('')+
  (includeWeather?hskWeatherHealthConsequences(actorId):'');
 return html?'<section class="panel wide"><h3>Čekající pravidlové následky Skill Tests</h3><p class="muted">Nevyřešené kritické hody jsou dostupné i po obnovení stránky; původní hod se znovu nehází.</p>'+html+'</section>':'';
}
let pendingCalendarGMTest=null;
