// A standing 24h food/water policy records attested assumptions only.
// The policy DOES NOT change the clock or the actor's medical condition.
document.addEventListener('submit',e=>{
 const form=e.target;if(!form?.matches?.('[data-nutrition-policy-form]'))return;
 e.preventDefault();e.stopImmediatePropagation();
 try{
  const clock=data.campaignClock;if(!clock)throw Error('Není vybraná kampaň');
  const f=new FormData(form),ids=f.getAll('nutritionActorIds');
  const activePerson=activeProvisionActor();
  if(form.dataset.provisionScopeActor&& (ids.length!==1||ids[0]!==form.dataset.provisionScopeActor||form.dataset.provisionScopeActor!==activePerson?.id||!personalProvisionContext()))throw Error('Individuální režim nepatří aktuálně vybrané postavě.');
  const allowed=new Set(calendarMemberIds(clock,data.characters).map(c=>c.id));
  if(!ids.length||ids.some(id=>!allowed.has(id))||new Set(ids).size!==ids.length)throw Error('Vyberte platné postavy současné kampaně');
  const enabled=f.get('policyAction')==='activate';
  const inventoryMode=enabled&&f.get('sourceMode')==='inventory';
  const inventoryWater=enabled&&inventoryMode&&f.get('inventoryWater')==='yes';
  if(enabled&&f.get('foragingOnly')!=='yes')throw Error('Potvrďte úplnost dostupných zdrojů potravy a vody.');
  if(enabled&&!inventoryMode)for(const actorId of ids){assertExclusiveForagingProven({inventory:activeRationInventory(),actorId});
   if(availablePhysicalWater(data.journal,campaignKey(clock),actorId,clock.minute).length)throw Error('Postava má doloženou vodu v naplněné nádobě: výhradní Foraging není prokázán.');}
  const stocks=inventoryMode?ids.flatMap(actorId=>createFreshRationStocks({inventory:data.inventory,journal:data.journal,campaignId:campaignKey(clock),actorId,minute:clock.minute,freshConfirmed:f.get('freshRations')==='yes'})):[];
  // Selecting an inventory source does not require stock to be present NOW:
  // an empty physical inventory is an actual shortage, never fictitious food.
  for(const actorId of ids)assertNutritionPolicyBoundary(data.journal,campaignKey(clock),actorId,clock.minute);
  const proofs=ids.map(actorId=>createNutritionPolicy({campaignId:campaignKey(clock),minute:clock.minute,actorId,
   foodNeed:f.get('autoNeeds')==='yes'?1:Number(f.get('foodNeed')),waterNeed:f.get('autoNeeds')==='yes'?1:Number(f.get('waterNeed')),autoNeeds:f.get('autoNeeds')==='yes'&&enabled,foragingOnly:enabled&&!inventoryMode,inventoryRations:inventoryMode,inventoryWater,enabled}));
  if(mutate(()=>{data.journal.push(...stocks.map(p=>({id:uuid(),characterId:p.actorId,calendarCampaignId:p.campaignId,campaignMinute:p.minute,createdAt:stamp(),title:'HMK · doložené potraviny',body:`${p.quantity} ks ${p.name} · ${p.itemId}; čerstvost potvrzena GM; bez posunu času`,calendarInventoryRationStock:p})));
   data.journal.push(...proofs.map(p=>({id:uuid(),characterId:p.actorId,calendarCampaignId:p.campaignId,
   campaignMinute:p.minute,createdAt:stamp(),title:'HMK · denní zásobovací režim',
   body:p.enabled?`Od teď: ${p.autoNeeds?"adaptivní (výchozí 1/1)":p.foodNeed+" jídlo, "+p.waterNeed+" voda"} / 24 h, ${p.inventoryRations?'čerstvé inventární dávky + Foraging':'výhradně Foraging'}${p.inventoryWater?' + potvrzená voda z nádob':''}. Hodiny beze změny.`:'GM pozastavil automatické denní zásobování; čas se nemění.',
   calendarNutritionPolicy:p})));}))notice='Zásobovací režim a doložené fyzické zásoby byly uloženy; den se zúčtuje až po posunu GM.';
 }catch(err){alert('Režim výživy nebyl uložen: '+err.message)}
},true);
// GM's explicit continuous provisioning: no fake carried stock, no hidden checkboxes.
// Only this actor is affected. Changing a mode starts at the current GM minute.
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-provision-assure]');if(!b)return;
 e.preventDefault();e.stopImmediatePropagation();
 try{
  const clock=data.campaignClock,actorId=b.dataset.actorId,mode=b.dataset.provisionAssure;
  if(!clock||!personalProvisionContext()||!['yes','no'].includes(mode))throw Error('Neplatná volba zásobování');
  const shown=activeProvisionActor();
  assertPersonalProvisionAction(shown);
  if(!shown||shown.id!==actorId)throw Error('Změna by zasáhla jinou postavu než tu zobrazenou');
  const cid=campaignKey(clock);
  if(pcShelteredStayAt(data.journal,cid,actorId,clock.minute))throw Error('Postava je v zajištěném prostředí. Zásobování je automaticky zajištěno; pro změnu nejprve ukončete tento pobyt v Přehledu a čase.');
  const current=gmProvisionedAt(data.journal,cid,actorId,clock.minute);
  const next=mode==='yes';
  if(current===next){notice=next?'Zásobování GM je již průběžně doložené.':'Zásobování z fyzických zásob již platí.';render();return;}
  // A timed source change does NOT start another nutrition day. The original
  // 24h ledger continues and counts GM-covered minutes only at day closure.
  const base=activeNutritionPolicies(data.journal,cid,[actorId])[0];
  const proof=base?createNutritionProvisionSwitch({campaignId:cid,actorId,minute:clock.minute,provisioned:next}):null;
  const policy=base?null:createNutritionPolicy({campaignId:cid,minute:clock.minute,actorId,foodNeed:1,waterNeed:1,
   enabled:true,autoNeeds:true,gmProvisioned:next,inventoryRations:!next,inventoryWater:!next});
  if(!uiConfirm(next?`GM potvrzuje průběžný přístup ${shown.name} k jídlu a vodě od ${displayCampaignMinute(clock.minute)}? Část dne před změnou zůstane zachována.`:`Od ${displayCampaignMinute(clock.minute)} ukončit GM zajištěný přístup pro ${shown.name}? Zbývající potřeba se uhradí jen doloženými zdroji.`))return;
  if(mutate(()=>data.journal.push({id:uuid(),characterId:actorId,calendarCampaignId:cid,campaignMinute:clock.minute,createdAt:stamp(),
   title:next?'HMK · zásobování GM od této minuty':'HMK · konec zásobování GM',
   body:'Rozhodnutí platí od '+displayCampaignMinute(clock.minute)+'; předchozí část dne se nemění, spotřeba se vyúčtuje po 24 hodinách v půldenních dávkách.',
   ...(proof?{calendarNutritionProvisionSwitch:proof}:{calendarNutritionPolicy:policy})
  })))notice='Změna zásobování platí od nynější minuty. Denní účet zohlední skutečnou dobu zajištěného jídla a vody.';
 }catch(err){alert('Zásobování nebylo změněno: '+err.message)}
},true);
// Preview is read-only UI and never substitutes the authoritative Foraging ledger.
function updatePartyRationPreview(form){
 if(!form?.hasAttribute?.('data-party-food-available'))return;
 const label=form.querySelector('[data-party-ration-preview]');if(!label)return;
 const count=form.querySelectorAll('input[name="rationActorIds"]:checked').length;
 const foodEach=Number(form.elements.namedItem('foodEach')?.value||0),waterEach=Number(form.elements.namedItem('waterEach')?.value||0);
 const food=count*foodEach,water=count*waterEach;
 const maxFood=Number(form.dataset.partyFoodAvailable),maxWater=Number(form.dataset.partyWaterAvailable);
 const valid=count>0&&(food>0||water>0)&&food<=maxFood+1e-8&&water<=maxWater+1e-8;
 const qty=n=>Number.isInteger(n)?czCount(n,'dávka','dávky','dávek'):String(n).replace('.',',')+' dávky';
 label.textContent=count?`Celkem pro ${czCount(count,'postavu','postavy','postav')}: ${qty(food)} jídla z ${qty(maxFood)} a ${qty(water)} vody z ${qty(maxWater)}. `+
  (food>maxFood||water>maxWater?'Nedostatek společných zásob – snižte dávku nebo počet příjemců.':food===0&&water===0?'Zvolte alespoň jednu nenulovou dávku.':'Při potvrzení se použijí skutečné účetní doklady.'):
  'Vyberte postavy, kterým chcete společné nálezy přidělit.';
 const submit=form.querySelector('button[type="submit"]');if(submit)submit.disabled=!valid;
}
document.addEventListener('change',e=>{
 const form=e.target.closest?.('[data-foraging-batch-rations][data-party-food-available]');
 if(form)updatePartyRationPreview(form);
},true);
