document.addEventListener('click',e=>{
 const auto=e.target.closest?.('[data-herb-auto],[data-herb-shared]');if(auto){
  const f=auto.closest('form'),shared=auto.matches('[data-herb-shared]'),one=shared?secureAutoDie(10):null;
  for(const input of f.querySelectorAll('input[name^="dice_"]')){
   const n=input.name.endsWith('_0')?(shared?one:secureAutoDie(10)):secureAutoDie(6);
   input.value=String(n);input.dataset.herbGenerated=input.value;
  }
  if(shared)f.elements.namedItem('singlePotencyRoll').checked=true;
  auto.textContent=shared?'⚄ Společný d10 '+one+' a nezávislé 2d6 vygenerovány':'⚄ Hody byly vygenerovány';return;
 }
 const b=e.target.closest?.('[data-herb-shelf-roll]');if(b){const x=b.closest('form')?.elements.namedItem('shelfD6');if(x){x.value=String(secureAutoDie(6));x.dataset.herbGenerated=x.value;b.textContent='⚄ d6 '+x.value;}}
},true);
document.addEventListener('input',e=>{if(e.target?.matches?.('[data-herb-assess] input[name^="dice_"], [data-herb-complete] [name="shelfD6"]')&&
 e.target.dataset.herbGenerated!==e.target.value)delete e.target.dataset.herbGenerated;},true);
document.addEventListener('click',e=>{const b=e.target.closest?.('[data-hallucinogenic-d20]');if(!b)return;const x=b.closest('form')?.elements.namedItem('d20');if(x){x.value=String(secureAutoDie(20));x.dataset.herbGenerated=x.value;}},true);
document.addEventListener('input',e=>{if(e.target?.matches?.('[data-hallucinogenic-dream] input[name="d20"]')&&e.target.dataset.herbGenerated!==e.target.value)delete e.target.dataset.herbGenerated;},true);
document.addEventListener('submit',e=>{
 const f=e.target;if(!f?.matches?.('[data-hallucinogenic-dream],[data-hallucinogenic-trance-start],[data-hallucinogenic-veil],[data-hallucinogenic-trance-abort]'))return;
 e.preventDefault();e.stopImmediatePropagation();
 try{
  const clock=data.campaignClock;if(!clock)throw Error('Chybí GM kalendář');
  const fd=new FormData(f),journal=data.journal,campaignId=campaignKey(clock),minute=clock.minute;
  const targetId=String(fd.get('targetId')||''),who=character(targetId);
  if(!who||!calendarMemberIds(clock,data.characters).some(c=>c.id===targetId))throw Error('Příjemce není v aktuální kampani');
  let type,proof,title,body;
  if(f.matches('[data-hallucinogenic-dream]')){
   const d20=Number(fd.get('d20')),aura=Number(fd.get('aura'));
   if(aura!==who.hmk?.attributes?.aur)throw Error('Aura nesouhlasí s ověřenou postavou');
   proof=createHallucinogenicLucidDream({journal,campaignId,applicationId:String(fd.get('applicationId')),minute,targetId,aura,
    willIndex:Number(fd.get('willIndex')),d20,dieOrigin:f.elements.namedItem('d20').dataset.herbGenerated===String(d20)?'cryptographic-software-die':'manual',
    gmConfirmed:fd.get('gmConfirmed')==='on',savirisTracked:true,reembodimentTracked:true});
   type='calendarHerbLucidDream';title='HMK 75/292 · Hallucinogenic Lucid Dream';
   body='Skutečný d20 '+d20+', Aura '+aura+'; Lucid Dream '+proof.dreamRounds+' bojových kol. Saviris a Reembodiment zůstávají samostatnými hody.';
  }else if(f.matches('[data-hallucinogenic-trance-start]')){
    if(combatActorLocked93725(targetId))throw Error('Zahájení Trance účastníka Initiative patří do Combat.');
   const ml=skillValueForJournal(who,['Trance']);
   proof=createHallucinogenicTranceStart({journal,campaignId,applicationId:String(fd.get('applicationId')),minute,targetId,
    tranceSkillML:ml,consciousConfirmed:fd.get('conscious')==='on',uninterruptedIntended:fd.get('uninterrupted')==='on',gmConfirmed:true});
   type='calendarHerbHallucinogenicTranceStart';title='HMK 75/291 · Hallucinogenic Trance start';
   body='Nepřerušená Trance zahájena; Lift the Veil splatné '+proof.dueMinute+'; bonus k budoucímu Transcendence '+proof.transcendenceBonus+'.';
  }else if(f.matches('[data-hallucinogenic-veil]')){
   proof=createHallucinogenicVeil({journal,campaignId,startId:String(fd.get('startId')),minute,targetId,
    concentrationUninterrupted:fd.get('uninterrupted')==='on',gmConfirmed:fd.get('gmConfirmed')==='on',transcendenceTracked:true});
   type='calendarHerbHallucinogenicVeil';title='HMK 75/291 · Hallucinogenic Lift the Veil';
   body='GM doložil nepřerušenou Trance; bonus Transcendence '+proof.transcendenceBonus+'; výsledek Transcendence a astrální následky nejsou vyhodnoceny.';
  }else{
   proof=createHallucinogenicTranceAbort({journal,campaignId,startId:String(fd.get('startId')),minute,targetId,reason:String(fd.get('reason')||''),gmConfirmed:fd.get('gmConfirmed')==='on'});
   type='calendarHerbHallucinogenicTranceAbort';title='HMK 75/291 · Hallucinogenic Trance přerušena';
   body='Trance přerušena: '+proof.reason+'. Bez astrálního účinku a bez posunu času.';
  }
  const entry={id:uuid(),characterId:targetId,calendarCampaignId:campaignId,campaignMinute:minute,
   createdAt:stamp(),title,body,[type]:proof};
  if(mutate(()=>data.journal.push(entry))){notice=title+' · GM čas zůstal beze změny';render();}
 }catch(err){alert('Hallucinogenic nebyl uložen: '+err.message)}
},true);

