 e.preventDefault();e.stopImmediatePropagation();
 const kind=btn.dataset.hazardCreate;
 if(view!=='sheet'||activeSheetSection!=='hazards'||!character(selected)||!['fire','cold-water','poison','disease','sleep'].includes(kind))return;
