document.addEventListener('submit',e=>{
 const f=e.target;
 if(!['campaign-start-form','campaign-advance-form','campaign-anchor-wound-form','campaign-anchor-procedure-form'].includes(f.id))return;
 e.preventDefault();e.stopImmediatePropagation();
 const v=Object.fromEntries(new FormData(f));
 const parse=(x)=>/^\d+$/.test(String(x??''))?Number(x):NaN;
 try{
  if(f.id!=='campaign-advance-form'&&v.gmConfirmed!=='yes')throw Error('GM musí potvrdit skutečný čas');
  if(f.id==='campaign-start-form'){
   if(data.campaignClock&&!calendarCreating)throw Error('Kalendář už existuje');
   const memberIds=new FormData(f).getAll('characterId').filter(id=>availableCampaignCharacters(data).some(c=>c.id===id));
   if(data.characters.length&&!memberIds.length)throw Error('Vyberte alespoň jednu postavu kampaně');
   let next=createCampaignCalendar({day:parse(v.day),hour:parse(v.hour),minute:parse(v.minute),label:v.label,
    gmConfirmed:true,eventId:uuid(),campaignId:uuid(),characterIds:memberIds});
   if(v.setTR==='yes')next=setCampaignTROrigin(next,{year:parse(v.trYear),month:parse(v.trMonth),day:parse(v.trDay),eventId:uuid(),confirmed:true});
   assertCompatibleLiveEffectTimeAxis(next,data.calendarEvidenceArchives??[],data.characters,memberIds,{identicalDayAxis:v.sameDayAxis==='yes'});
   const restored=recoverCalendarEvidence(next,data.calendarEvidenceArchives??[],memberIds,{identicalDayAxis:v.sameDayAxis==='yes',idFactory:uuid});
   next=restored.clock;validateCampaignCalendar(next);
   if(!uiConfirm('Založit kalendář '+displayCampaignMinute(next.minute)+' pro '+memberIds.length+' postav? Obnovené časové počátky: '+restored.recovered+'. Neurčitelné časy: '+restored.unmapped+'.'))return;
   if(mutate(()=>{const created=beginAdditionalCalendar(data,next);data.campaignClock=created.campaignClock;data.campaignClocks=created.campaignClocks;data.campaignActorBranches=created.campaignActorBranches;data.characters=created.characters;data.inventory=created.inventory;})){calendarUI=null;calendarCreating=false;calendarLanding=false;render();}return;
  }
  if(!data.campaignClock)throw Error('Kalendář ještě nebyl založen');
  if(f.id==='campaign-advance-form'){
   if(combatInitiativeSequence)throw Error('Během aktivní Initiative nelze posouvat hodiny kampaně bez vyřešení bojových kol');
   const days=parse(v.days),hours=parse(v.hours),minutes=parse(v.minutes);
   if(![days,hours,minutes].every(Number.isSafeInteger)||hours>23||minutes>59)throw Error('Zadejte celé dny a HH:MM');
   const next=advanceCampaignCalendar(data.campaignClock,{deltaMinutes:days*DAY_MINUTES+hours*60+minutes,
    reason:v.reason,eventId:uuid(),gmConfirmed:true,characters:data.characters,journal:data.journal,inventory:data.inventory});
   if(!uiConfirm('Posunout celou kampaň na '+displayCampaignMinute(next.minute)+'? Splatné dokončené činnosti budou vyhodnoceny automaticky.'))return;
   mutate(()=>{data.campaignClock=next;applyDeterministicCalendarOnsets();},{gmClockAdvance:true});return;
  }
  const days=parse(v.days),hours=parse(v.hours),minutes=parse(v.minutes);
  if(![days,hours,minutes].every(Number.isSafeInteger)||hours>23||minutes>59)throw Error('Doložte počet dní a HH:MM');
  const elapsedMinutes=days*DAY_MINUTES+hours*60+minutes;
  let kind,characterId,woundId=null,episodeId=null;
  if(f.id==='campaign-anchor-wound-form'){
   [characterId,woundId]=String(v.wound??'').split('::');kind='wound';
   if(!character(characterId)?.hmk?.healthState?.wounds?.some(w=>w.id===woundId&&!w.healed))throw Error('Rána už neexistuje nebo je zhojená');
  }else{
   [kind,characterId,episodeId]=String(v.origin??'').split('::');
   const s=character(characterId)?.hmk?.healthState;
   if(!s||!((kind==='extended-shock'&&s.extendedShock)||(kind==='coma'&&s.coma?.active)||(kind==='blood-loss'&&s.bloodLoss?.bp>0)||(kind==='poison'&&(s.toxinCourses??[]).some(t=>t.id===episodeId&&['incubating','active'].includes(t.status)))||(kind==='disease'&&(s.diseaseCourses??[]).some(t=>t.id===episodeId&&['pending-profile','incubating','active'].includes(t.status)))||(kind==='weather'&&(s.environmentalHazards??[]).some(h=>h.id===episodeId&&h.active))||(kind==='sleep'&&s.sleepDeprivation?.status==='awake'&&s.sleepDeprivation?.episodeId===episodeId)||(kind==='aural'&&character(characterId)?.hmk?.arcane?.auralShockLevels>0&&episodeId==='aural-legacy')))throw Error('Procedura již není aktivní');
  }
  const next=anchorCampaignOrigin(data.campaignClock,{kind,characterId,woundId,episodeId,elapsedMinutes,
   gmConfirmed:true,eventId:uuid()});
  if(!uiConfirm('Trvale potvrdit počátek '+kind+' před '+elapsedMinutes+' minutami?'))return;
  mutate(()=>{data.campaignClock=next;});
 }catch(err){alert('Kalendář nebyl změněn: '+err.message);}
},true);
