// v93.480: audited actor-specific ration acquisition. Button click is the GM
// attestation; no assumed ingredients or separate food counter is created.
document.addEventListener('submit',e=>{
 const form=e.target;if(!form?.matches?.('[data-provision-food-acquire]'))return;
 e.preventDefault();e.stopImmediatePropagation();
 try{
  if(!personalProvisionContext()||combatInitiativeSequence)throw Error('Zásoby lze měnit jen pro zvolenou postavu mimo boj');
  const clock=data.campaignClock,actor=activeProvisionActor();
  const v=Object.fromEntries(new FormData(form));
  assertPersonalProvisionAction(actor);
  if(!actor||v.actorId!==actor.id)throw Error('Změna se netýká aktuálně zobrazené postavy');
  const qty=Number(v.days),rationId=String(v.rationType),mode=String(v.mode);
  if(![1,2,3,5,7].includes(qty)||!['hmk:gear:hmk-p120-026','hmk:gear:hmk-p120-027'].includes(rationId)||!['buy','other'].includes(mode))throw Error('Neplatný počet nebo druh potravin');
  const source=item(rationId),offer=source&&libraryPurchaseOffer(source);
  if(!source||!offer||offer.quantity!==1||!Number.isSafeInteger(offer.pricePence))throw Error('Tištěné potraviny nemají doložený katalog a cenu');
  const amount=qty*offer.pricePence,reason=String(v.origin||'').trim();
  if(mode==='other'&&(reason.length<3||reason.length>120))throw Error('GM musí uvést skutečný zdroj potravy');
  if(mode==='buy')prepareLibraryPurchase(actor,amount,activeCampaignCashKey(actor));
  if(!ask(mode==='buy'?`Potvrdit nákup ${qty} ${source.name} za ${amount}d pro ${actor.name}?`:`GM potvrzuje skutečné převzetí potravin (${qty} dní) postavou ${actor.name} (${reason})?`))return;
  const committed=mutate(()=>{
   const live=character(actor.id),campaignId=campaignKey(data.campaignClock),minute=data.campaignClock.minute;
   assertPersonalProvisionAction(live);
   if(!live||activeCampaignCashKey(live)===undefined||minute!==clock.minute||combatInitiativeSequence)throw Error('Změnil se čas, členství nebo stav Initiative');
   const nowSource=item(rationId),nowOffer=libraryPurchaseOffer(nowSource);
   if(!nowSource||nowOffer?.pricePence!==offer.pricePence||nowOffer?.quantity!==1)throw Error('Původní nabídka již není platná');
   if(mode==='buy')prepareLibraryPurchase(live,amount,campaignId);
   const txId=uuid(),invId=uuid(),createdAt=stamp();
   const inv={id:invId,currentWQ:null,characterId:actor.id,sourceItemId:rationId,snapshot:structuredClone(nowSource),quantity:qty,condition:'',slot:'carried',
    acquisition:{mode:mode==='buy'?'buy':'free',transactionId:txId,at:createdAt,pricePence:mode==='buy'?amount:0,campaignId,campaignMinute:minute}};
   data.inventory.push(inv);
   if(mode==='buy')recordCampaignCashPurchase(live,{campaignId,minute,id:txId,at:createdAt,amountPence:amount,label:nowSource.name,
    inventoryIds:[invId],purchasedItems:[{inventoryId:invId,sourceItemId:rationId,quantity:qty,snapshot:structuredClone(nowSource)}]});
   const stocks=createFreshRationStocks({inventory:[inv],journal:data.journal,campaignId,actorId:actor.id,minute,freshConfirmed:true});
   if(stocks.length!==1)throw Error('Nebylo možné založit fyzické potraviny HMK');
   data.journal.push({id:uuid(),characterId:actor.id,calendarCampaignId:campaignId,campaignMinute:minute,createdAt,
    title:mode==='buy'?'HMK · nákup potravin':'HMK · potvrzené převzetí potravin',
    body:`${qty} dávek · ${qty*3} lb · ${mode==='buy'?amount+'d':'zdroj: '+reason}; čas se nemění`,calendarInventoryRationStock:stocks[0]});
  });
  if(committed)notice=`Postava ${actor.name} získala ${qty} fyzických dávek jídla (${qty*3} lb). Potvrzená spotřeba a čas zůstaly beze změny.`;
 }catch(err){alert('Pořízení zásob: '+err.message)}
},true);
// v93.483 — acquire ONLY the two witnessed HMK water vessels in the
// original Library/inventory/cash ledger; an empty vessel is not drinking water.
document.addEventListener('submit',e=>{
 const form=e.target;if(!form?.matches?.('[data-provision-vessel-acquire]'))return;
 e.preventDefault();e.stopImmediatePropagation();
 try{
  if(!personalProvisionContext()||combatInitiativeSequence)throw Error('Nádobu pořizujte pro vybranou postavu mimo Initiative.');
  const clock=data.campaignClock,actor=activeProvisionActor();
  const v=Object.fromEntries(new FormData(form));
  assertPersonalProvisionAction(actor);
  if(!actor||actor.id!==v.actorId)throw Error('Nádoba nepatří právě vybrané postavě');
  const id=String(v.vesselId||''),mode=provisionGuideRoute==='buy'?'buy':'other',reason='Vlastní zásoby · bezplatné převzetí';
  if(!['have','buy','other'].includes(provisionGuideRoute)||!['hmk:gear:hmk-p120-040','hmk:gear:hmk-p121-043'].includes(id))throw Error('Vyberte doloženou nádobu HMK');
  if(mode==='other'&&provisionGuideRoute==='other')throw Error('Jiný zdroj vyžaduje doložené převzetí v Knihovně; osobní Vlastní zásoby zůstávají zdarma');
  const source=item(id),offer=source&&libraryPurchaseOffer(source),cost=offer?.pricePence;
  const draft=source?{sourceItemId:id,snapshot:structuredClone(source),quantity:1,slot:'carried'}:null;
  if(!draft||waterContainerCapacity(draft)===null||!Number.isSafeInteger(cost)||offer.quantity!==1)throw Error('Nádoba nemá doložený katalog, hmotnost nebo cenu');
  if(mode==='buy')prepareLibraryPurchase(actor,cost,activeCampaignCashKey(actor));
  if(!ask(mode==='buy'?`Koupit ${source.name} za ${cost}d pro ${actor.name}?`:`Převzít prázdnou nádobu ${source.name} zdarma do vlastních zásob ${actor.name}?`))return;
  if(mutate(()=>{
   const live=character(actor.id),campaignId=campaignKey(data.campaignClock),minute=data.campaignClock.minute;
   assertPersonalProvisionAction(live);
   if(!live||minute!==clock.minute||activeCampaignCashKey(live)===undefined||combatInitiativeSequence)throw Error('Změna kampaně či postavy');
   if(mode==='buy')prepareLibraryPurchase(live,cost,campaignId);
   const actual=item(id),p=libraryPurchaseOffer(actual),invId=uuid(),txId=uuid(),createdAt=stamp();
   if(!actual||p?.pricePence!==cost||waterContainerCapacity({sourceItemId:id,snapshot:actual,quantity:1})===null)throw Error('Předmět již neodpovídá katalogu HMK');
   data.inventory.push({id:invId,characterId:actor.id,sourceItemId:id,snapshot:structuredClone(actual),quantity:1,currentWQ:null,condition:'',slot:'carried',acquisition:{mode:mode==='buy'?'buy':'free',transactionId:txId,at:createdAt,pricePence:mode==='buy'?cost:0,campaignId,campaignMinute:minute}});
   if(mode==='buy')recordCampaignCashPurchase(live,{campaignId,minute,id:txId,at:createdAt,amountPence:cost,label:actual.name,inventoryIds:[invId],purchasedItems:[{inventoryId:invId,sourceItemId:id,quantity:1,snapshot:structuredClone(actual)}]});
   data.journal.push({id:uuid(),characterId:actor.id,calendarCampaignId:campaignId,campaignMinute:minute,createdAt,
    title:mode==='buy'?'HMK · nákup prázdné nádoby':'HMK · převzetí prázdné nádoby',body:`${actual.name} · ${mode==='buy'?cost+'d':'zdroj: '+reason}; bez vody a bez posunu času`});
  }))notice=`Postava ${actor.name} získala prázdnou nádobu. Vodu musí doložit zvlášť.`;
 }catch(err){alert('Pořízení nádoby: '+err.message)}
},true);
