document.addEventListener('submit',e=>{
 if(e.target?.id!=='inventory-chest-outfit-form')return;e.preventDefault();e.stopImmediatePropagation();
 const v=Object.fromEntries(new FormData(e.target));
 if(view!=='sheet'||activeSheetSection!=='inventory'||String(v.actorId)!==selected||combatActorLocked93725(selected))return alert('Změnil se vlastník nebo režim Combat.');
 try{
  const plan=previewChestOutfit(data,{ownerId:selected,location:v.location,mode:v.mode});
  if(!plan.ready)throw Error(plan.reason);
  if(!plan.ids.length&&!plan.preview.equipIds.length&&!plan.preview.unequipIds.length)
   throw Error('Nejlepší přípustná kombinace už je oblečená; přesun z této truhly by ochranu ani vrstvení nezlepšil.');
  if(!ask('Vybraná sestava: '+plan.preview.names.join(', ')+'\nZ truhly vyzvednout '+plan.ids.length+' článků ('+plan.names.join(', ')+').\nDoložené pravidlo: '+plan.preview.proof+'\nProvést všechny přesuny a převlečení?'))return;
  const result=applyChestOutfit(data,{ownerId:selected,location:v.location,mode:v.mode,confirmed:v.confirmed==='yes',idFactory:uuid,createdAt:stamp()});
  const load=resolveCombatantLoad({character:character(selected),inventory:result.inventory});
  if((load.layeringFeasibility?.status==='forbidden'&&!load.printedSuit)||load.layeringStatus==='violation'||load.bulkReady===false)throw Error('Výsledná ochrana/vrstvy nebyly pravidlově ověřeny.');
  if(!result.changed){overlay=null;render();alert('Původní sestava je již optimální; žádná položka nebyla přesunuta.');return;}
  if(mutate(()=>{data.inventory=result.inventory;data.journal=result.journal;})){overlay=null;render();}
 }catch(err){alert('Převlečení z truhly nebylo provedeno: '+err.message);}
},true);
document.addEventListener('click',e=>{
 const t=e.target.closest('[data-armour-autolayer]');if(!t)return;
 e.preventDefault();e.stopImmediatePropagation();
 const id=t.dataset.armourAutolayer;
 if(view!=='sheet'||selected!==id||!character(id))return;
 if(combatActorLocked93725(id))return alert('Vrstvení účastníka boje vyžaduje Combat akci.');
 const current=data.inventory.filter(x=>x.characterId===id);
 const preview=previewExistingArmourArrangement(current);
 if(!preview.ready)return alert(preview.reason);
 if(!preview.placements.length)return;
 const original=resolveCombatantLoad({character:character(id),inventory:activeRationInventory()});
 if(original.layeringFeasibility?.status==='forbidden')return alert('Skutečně zakázané vrstvy nelze pouhým přeuspořádáním legalizovat.');
 if(!ask('Zapsat automaticky ověřené pořadí oblečených vrstev? Žádný předmět nebude odebrán ani přesunut.'))return;
 const done=mutate(()=>{
  const targets=new Map(preview.placements.map(x=>[x.id,x]));
  for(const item of data.inventory){if(item.characterId!==id||!targets.has(item.id))continue;
   const p=targets.get(item.id);if(item.slot!=='worn')throw Error('Během rozhodnutí se změnilo oblečení');
   item.layerOrder=p.layerOrder;item.layerSlot=p.layerSlot;item.bulkExceptionZones=[...p.bulkExceptionZones];
  }
  const verified=resolveCombatantLoad({character:character(id),inventory:activeRationInventory()});
  if(!verified.bulkReady||!verified.encReady||verified.layeringStatus==='violation')throw Error('Nové pořadí neprošlo pravidlovou kontrolou HMK');
 });
 if(done){selected=id;view='sheet';render();}
},true);
