 if(animals.some(c=>!c?.hmk?.verifiedMountedBreed||!c.hmk.healthState||!(data.campaignClock.characterIds??[]).includes(c.id)))
  throw Error('Zvíře musí mít ověřený stav a patřit do této kampaně.');
