/** Independent of sequential rule-engine errors: show all already knowable
 * requirements at the first evaluation. Dependent CF/Hazard/Encounter tasks
 * are added only once their original roll is known. */
/** A pre-existing dated obligation is independent of the travel receipt.
 * Detect it before the GM has spent time resolving all of the episode dice.
 * This is deliberately NON-mutating: the existing medical executor needs its
 * real due minute, so we must never falsify a completed d100 at the start.
 */
function episodeIndependentDeadlines(form){
 const clock=data.campaignClock;if(!clock)return [];
 const duration=Number(form.elements.namedItem('minutes')?.value);
 if(!Number.isSafeInteger(duration)||duration<1||duration>10080)return [];
 const end=clock.minute+duration;
 const journalIds=new Map(data.journal.map(j=>[j.id,j]));
 try{return campaignCalendarAgenda(clock,data.characters,data.journal,data.inventory).all.filter(item=>
  // An already-overdue medical obligation must remain visible and actionable.
  // The original scheduler still decides whether its evidence permits any advance.
  Number.isSafeInteger(item.minute)&&item.minute<end&&
  // These obligations belong to the still-running episode; they must be
  // completed in its own checklist, never duplicated as external events.
  !(item.kind==='skill-critical'&&isTravelEpisodeReceipt(journalIds.get(item.originId)))&&
  // An automatic Poison/Disease onset can be applied by the original clock
  // executor; it is not itself a new d100 at this point.
  !['poison','disease'].includes(item.kind));}
 catch{return [];}
}
/** Recompute the medical timeline from immutable original evidence on every
 * evaluation. A draft roll is only a proposal; it cannot alter the real clock.
 */
function episodeTimedRolls(form){
 try{const v=JSON.parse(form.elements.namedItem('episodeTimedRollsJson')?.value||'{}');
  return v&&typeof v==='object'&&!Array.isArray(v)?v:{};
 }catch{return {};}
}
// The Travel UI invokes only health timelines. HMK 182 Move/Charge/Double
// Move aggravation belongs to Combat turn actions; do not infer those turns
// from multi-hour travel duration or from the trekking pace choices.
/** Read-only routing of existing dated medical obligations.
 * Travel must NEVER perform a separate medical d100 or advance a health state.
 * The original calendar and treatment/healing forms own the actual resolution.
 * An interval ending exactly at the due minute is legal; the NEXT interval
 * must first resolve that obligation in the original module.
 */
function episodeTimedMedical(form,{strict=false}={}){
 const requirements=episodeIndependentDeadlines(form).filter(x=>EPISODE_TIMED_COURSE_KINDS.has(x.kind))
  .map(x=>({key:x.id,kind:x.kind,characterId:x.characterId,dueMinute:x.minute,
   woundId:x.woundId??null,sourceId:x.sourceId??null,episodeId:x.episodeId??null,
   elapsedMinutes:x.elapsedMinutes??null,
   reason:x.description||'Povinná zdravotní kontrola v původním modulu'}));
 return {requirements,changes:[],incapacitations:[],complete:requirements.length===0};
}

/** GM memo reminders are reviewable without fabricated skill or health dice.
 * Real skills, wounds, timers and poisons stay mandatory in their own engine.
 * IDs and deadline must match the original pre-existing plan exactly. */
function episodeGMReviewData(form){
 try{const raw=JSON.parse(form.elements.namedItem('episodeGMReviewedJson')?.value||'{}');
  return raw&&typeof raw==='object'&&!Array.isArray(raw)?raw:{};
 }catch{return {};}
}
function episodeGMReviews(form){
 // No GM calendar action may be completed implicitly by Travel.
 return {pending:[],reviewed:[]};
}

const EPISODE_TIMED_COURSE_KINDS=new Set(['malnutrition-course','poison','disease','healing','infection','blood-loss','grim','extended-shock','coma','weather-course','sleep-deprivation']);
function episodeOtherTimedTasks(form){return episodeIndependentDeadlines(form).filter(x=>!EPISODE_TIMED_COURSE_KINDS.has(x.kind));}
function episodeGMStagedClock(clock,reviewed){
 if(!reviewed.length)return clock;
 const next={...clock,planResolutions:[...(clock.planResolutions||[])]};
 for(const p of reviewed){
  if(p.destination!=='notes'||!p.requiresAction||p.resolution||!clock.plans?.some(x=>x.id===p.id&&x.trigger===p.trigger&&
   (x.trigger==='end'?x.endMinute:x.minute)===p.dueMinute))throw Error('Neplatné potvrzení časované události GM.');
  next.planResolutions.push({id:'travel-gm-review:'+clock.minute+':'+p.id,planId:p.id,minute:p.dueMinute,
   kind:'resolved',note:'GM zkontroloval časovanou připomínku během cestovní epizody.'});
 }
 return next;
}
